function contrastTextForHex(hex) {
  const match = String(hex || '').trim().match(/^#?([0-9a-f]{6})$/i);
  if (!match) return '#ffffff';
  const value = match[1];
  const channels = [0, 2, 4].map(pos => {
    const raw = parseInt(value.slice(pos, pos + 2), 16) / 255;
    return raw <= 0.03928 ? raw / 12.92 : Math.pow((raw + 0.055) / 1.055, 2.4);
  });
  const luminance = channels[0] * 0.2126 + channels[1] * 0.7152 + channels[2] * 0.0722;
  const blackContrast = (luminance + 0.05) / 0.05;
  const whiteContrast = 1.05 / (luminance + 0.05);
  return blackContrast > whiteContrast ? '#111827' : '#ffffff';
}

function renderBoardPie(pl) {
  const COLORS = [
    '#e3b74f', '#6dd87a', '#e06c6c', '#5bc8f5', '#f07dba',
    '#a374f7', '#fb8c5f', '#40e4e4', '#f9a8a8', '#7ede8a',
    '#8faeff', '#ffd166', '#d98ef5', '#6fecb5', '#ffb347',
    '#c9dc5a', '#ff9f7a', '#76d6ff', '#b6a0ff', '#f6d365',
    '#84e3c8', '#ff7f8f', '#a7c957', '#c77dff', '#64dfdf',
    '#f4a261', '#90be6d', '#4cc9f0', '#f28482', '#bde0fe',
  ];

  // Assign color by position in full roster so colors stay stable
  const allNames = S.playerRoster.map(p => p.name);
  const colorOf = name => COLORS[allNames.indexOf(name) % COLORS.length];

  // Only players with >0 points
  const active = pl.filter(p => (S.scores[p.name] || 0) > 0);
  const total = active.reduce((sum, p) => sum + (S.scores[p.name] || 0), 0);
  const cx = 150, cy = 150, r = 146;

  let sliceSVG = '';
  let labelSVG = '';
  let angle = -Math.PI / 2; // 12 o'clock

  active.forEach(p => {
    const pts = S.scores[p.name] || 0;
    const frac = pts / total;
    const sweep = frac * 2 * Math.PI;
    const end = angle + sweep;
    const color = colorOf(p.name);

    let pathD;
    if (active.length === 1) {
      // Full circle — SVG can't draw a 360° arc, use two halves
      pathD = [
        `M ${cx} ${cy}`,
        `L ${cx} ${cy - r}`,
        `A ${r} ${r} 0 1 1 ${cx} ${cy + r}`,
        `A ${r} ${r} 0 1 1 ${cx} ${cy - r}`,
        'Z'
      ].join(' ');
    } else {
      const x1 = (cx + r * Math.cos(angle)).toFixed(3);
      const y1 = (cy + r * Math.sin(angle)).toFixed(3);
      const x2 = (cx + r * Math.cos(end)).toFixed(3);
      const y2 = (cy + r * Math.sin(end)).toFixed(3);
      const large = sweep > Math.PI ? 1 : 0;
      pathD = `M ${cx} ${cy} L ${x1} ${y1} A ${r} ${r} 0 ${large} 1 ${x2} ${y2} Z`;
    }

    sliceSVG += `<path d="${pathD}" fill="${color}" stroke="#fffefd" stroke-width="1.5"/>`;

    // Keep every name visible. Narrow labels follow the slice center line from the outer edge inward.
    const mid = angle + sweep / 2;
    const baseLabelRadius = r * 0.70;
    const horizontalLabelRadius = sweep < 0.55 ? r * 0.79 : baseLabelRadius;
    const fs = sweep >= 0.65 ? 9 : sweep >= 0.22 ? 7.5 : 6.2;
    const availableArc = sweep * horizontalLabelRadius * 0.84;
    const estimatedTextWidth = String(p.name || '').length * fs * 0.56;
    const rotateLabel = sweep < 0.56 || availableArc < estimatedTextWidth;
    const textRadius = rotateLabel ? r * 0.95 : horizontalLabelRadius;
    const lx = cx + textRadius * Math.cos(mid);
    const ly = cy + textRadius * Math.sin(mid);
    const rotation = ((((mid + Math.PI) * 180 / Math.PI) % 360 + 360) % 360).toFixed(1);
    const transform = rotateLabel ? ` transform="rotate(${rotation} ${lx.toFixed(1)} ${ly.toFixed(1)})"` : '';
    const anchor = rotateLabel ? 'start' : 'middle';
    const labelColor = contrastTextForHex(color);
    labelSVG += `<text x="${lx.toFixed(1)}" y="${ly.toFixed(1)}"${transform} text-anchor="${anchor}" dominant-baseline="middle" font-family="'Google Sans Flex',sans-serif" font-size="${fs}" font-style="italic" fill="${labelColor}" style="pointer-events:none;">${esc(p.name)}</text>`;

    angle = end;
  });

  const legendHtml = pl.map(p => {
    const pts = S.scores[p.name] || 0;
    const pct = total && pts > 0 ? ((pts / total) * 100).toFixed(1) : '0.0';
    return `
    <div class="legend-item">
      <div class="legend-swatch" style="background:${colorOf(p.name)};"></div>
      <div class="legend-name">${esc(p.name)}</div>
      <div class="legend-meta">${pts}${countWord(pts, 'pt', 'pts')} · ${pct}%</div>
    </div>`;
  }).join('');

  return `
  <div class="board-pie-wrap">
    <div class="board-pie-graphic">
      ${active.length ? `<svg class="board-pie-svg" viewBox="0 0 300 300" xmlns="http://www.w3.org/2000/svg">
        ${sliceSVG}
        ${labelSVG}
      </svg>` : '<div class="empty" style="padding:20px 0;">No points scored yet</div>'}
    </div>
    <div class="board-legend">${legendHtml}</div>
  </div>`;
}

function getBoardClosenessStats(pl) {
  const completed = getHistoryEntries().filter(day => day?.wrapTime && Array.isArray(day.guesses));
  return pl.map(player => {
    let totalGap = 0;
    let count = 0;
    completed.forEach(day => {
      const guess = day.guesses.find(g => nameKey(g.name) === nameKey(player.name));
      if (!guess?.time) return;
      totalGap += boardClosenessGap(guess, day);
      count += 1;
    });
    return {
      name: player.name,
      count,
      avgGap: count ? totalGap / count : null
    };
  }).sort((a, b) => {
    if (a.avgGap === null && b.avgGap === null) return a.name.localeCompare(b.name);
    if (a.avgGap === null) return 1;
    if (b.avgGap === null) return -1;
    if (a.avgGap !== b.avgGap) return a.avgGap - b.avgGap;
    return a.name.localeCompare(b.name);
  });
}

function clockDistanceSec(a, b) {
  const diff = Math.abs(toSec(a) - toSec(b));
  return Math.min(diff, DAY_SEC - diff);
}

function boardClosenessGap(guess, day) {

  if (day?.noWinner) return clockDistanceSec(guess.time, day.wrapTime);

  const wrapSec = wrapTimelineSec(day.wrapTime, day);

  const guessSec = betTimelineSec(guess, wrapSec);

  return Math.abs(guessSec - wrapSec);

}

function didPlayerWinDay(name, day) {
  if (!name || day?.noWinner) return false;
  const winners = day?.winners ? day.winners.map(w => w.name) : (day?.winner ? [day.winner] : []);
  return winners.some(winnerName => nameKey(winnerName) === nameKey(name));
}

function renderBoardCloseness(pl) {
  const COLORS = [
    '#e3b74f', '#6dd87a', '#e06c6c', '#5bc8f5', '#f07dba',
    '#a374f7', '#fb8c5f', '#40e4e4', '#f9a8a8', '#7ede8a',
    '#8faeff', '#ffd166', '#d98ef5', '#6fecb5', '#ffb347',
    '#c9dc5a', '#ff9f7a', '#76d6ff', '#b6a0ff', '#f6d365',
    '#84e3c8', '#ff7f8f', '#a7c957', '#c77dff', '#64dfdf',
    '#f4a261', '#90be6d', '#4cc9f0', '#f28482', '#bde0fe',
  ];
  const allNames = S.playerRoster.map(p => p.name);
  const colorOf = name => COLORS[Math.max(0, allNames.indexOf(name)) % COLORS.length];
  const stats = getBoardClosenessStats(pl);
  const completed = getHistoryEntries().filter(day => day?.wrapTime && Array.isArray(day.guesses));
  const selectablePlayers = stats.filter(item => item.avgGap !== null).map(item => item.name);
  const allStatPlayers = stats.map(item => item.name);
  const activePlayer = allStatPlayers.includes(_closenessPlayer)
    ? _closenessPlayer
    : (selectablePlayers[0] || null);
  const points = [];
  if (!activePlayer) {
    return '<div class="empty" style="padding:20px 0;">No completed bets yet</div>';
  }
  completed.forEach((day, dayIdx) => {
    pl.forEach(player => {
      if (player.name !== activePlayer) return;
      const guess = day.guesses.find(g => nameKey(g.name) === nameKey(player.name));
      if (!guess?.time) return;
      points.push({
        name: player.name,
        day: dayIdx,
        date: displayToISO(day.date),
        unit: day.unit || 'main',
        gap: boardClosenessGap(guess, day),
        won: didPlayerWinDay(player.name, day)
      });
    });
  });

  const maxDay = Math.max(0, completed.length - 1);
  const allGaps = completed.flatMap(day => (day.guesses || [])
    .filter(guess => guess?.time)
    .map(guess => boardClosenessGap(guess, day)));
  const maxGap = points.length ? Math.max(...points.map(point => point.gap), 1) : Math.max(...allGaps, 1);
  const pointPosition = point => ({
    left: maxDay ? (point.day / maxDay) * 96 : 0,
    top: 88 - (point.gap / maxGap) * 78
  });
  const grouped = new Map();
  points.forEach(point => {
    if (!grouped.has(point.name)) grouped.set(point.name, []);
    grouped.get(point.name).push(point);
  });
  const lineSvg = [...grouped.entries()].flatMap(([name, playerPoints]) => {
    const color = colorOf(name);
    const sortedPoints = playerPoints.sort((a, b) => a.day - b.day);
    const segments = [];
    let segment = [];
    sortedPoints.forEach(point => {
      const previous = segment[segment.length - 1];
      if (previous && point.day !== previous.day + 1) {
        segments.push(segment);
        segment = [];
      }
      segment.push(point);
    });
    if (segment.length) segments.push(segment);
    return segments
      .filter(segmentPoints => segmentPoints.length > 1)
      .map(segmentPoints => {
        const pathPoints = segmentPoints.map(point => {
          const pos = pointPosition(point);
          return `${pos.left.toFixed(2)},${pos.top.toFixed(2)}`;
        }).join(' ');
        return `<polyline points="${pathPoints}" fill="none" stroke="${color}" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round" opacity=".9" vector-effect="non-scaling-stroke"/>`;
      });
  }).join('');
  const markerHtml = points.map(point => {
    const pos = pointPosition(point);
    const marker = `<span class="closeness-dot" style="background:${colorOf(point.name)};"></span>`;
    return `<a class="closeness-marker" href="#history-${encodeURIComponent(point.date)}" data-closeness-date="${esc(point.date)}" data-closeness-unit="${esc(point.unit)}" style="left:${pos.left.toFixed(2)}%; top:${pos.top.toFixed(2)}%;" title="${esc(point.name)} - ${esc(formatBoardExactCompactGap(point.gap))} off on ${esc(displayDayLabel(point.day + 1))}" aria-label="Open ${esc(displayDayLabel(point.day + 1))} in history">
      ${marker}
    </a>`;
  }).join('');
  const yTicks = [
    { value: maxGap, top: 10 },
    { value: maxGap / 2, top: 49 },
    { value: 0, top: 88 },
  ].map(tick =>
    `<div class="closeness-y-tick" style="top:${tick.top}%"><span>${esc(formatBoardCompactGap(tick.value))}</span></div>`
  ).join('');
  const dayTicks = completed.map((_, idx) => {
    const displayDay = displayDayNumber(idx + 1);
    if (Number(displayDay) % 5 !== 0) return '';

    const left = maxDay ? (idx / maxDay) * 96 : 0;
    return `<div class="closeness-x-tick" style="left:${left.toFixed(2)}%;"><span>${esc(displayDay)}</span></div>`;
  }).join('');

  const compareAccuracyStats = (a, b) => {
    const arrowPointsUp = _closenessOrderDir === 'asc';
    const compareNameAsc = (left, right) => left.name.localeCompare(right.name);
    const compareAvgAsc = (left, right) => {
      if (left.avgGap === null && right.avgGap === null) return compareNameAsc(left, right);
      if (left.avgGap === null) return 1;
      if (right.avgGap === null) return -1;
      if (left.avgGap !== right.avgGap) return left.avgGap - right.avgGap;
      if (right.count !== left.count) return right.count - left.count;
      return compareNameAsc(left, right);
    };

    if (_closenessOrder === 'name') {
      return arrowPointsUp ? b.name.localeCompare(a.name) : compareNameAsc(a, b);
    }

    if (_closenessOrder === 'bets') {
      if (a.count !== b.count) {
        return arrowPointsUp ? b.count - a.count : a.count - b.count;
      }
      return compareAvgAsc(a, b);
    }

    if (a.avgGap === null && b.avgGap === null) return compareNameAsc(a, b);
    if (a.avgGap === null) return 1;
    if (b.avgGap === null) return -1;
    if (a.avgGap !== b.avgGap) return arrowPointsUp ? b.avgGap - a.avgGap : a.avgGap - b.avgGap;
    if (b.count !== a.count) return b.count - a.count;
    return compareNameAsc(a, b);
  };
  const sortedStats = [...stats].sort(compareAccuracyStats);

  const nextClosenessOrder = _closenessOrder === 'accuracy' ? 'bets' : (_closenessOrder === 'bets' ? 'name' : 'accuracy');
  const closenessOrderLabel = _closenessOrder === 'accuracy' ? 'Time' : (_closenessOrder === 'bets' ? 'Bet' : 'Name');
  const orderControl = `
    <div class="accuracy-sort">
      <div class="accuracy-sort-controls">
        <button class="accuracy-sort-select${_closenessSortFlash === 'order' ? ' flash' : ''}" type="button" data-closeness-order="${nextClosenessOrder}">
          ${closenessOrderLabel}
        </button>
        <button class="accuracy-sort-dir${_closenessSortFlash === 'dir' ? ' flash' : ''}" type="button" data-closeness-order-dir="${_closenessOrderDir}" aria-label="Reverse order" style="--arrow-from:${Math.max(0, _closenessArrowTurns - 1) * 180}deg; --arrow-rotation:${_closenessArrowTurns * 180}deg">
          ↑
        </button>
      </div>
    </div>`;

  const legendHtml = sortedStats.map(item => {
    const color = colorOf(item.name);
    const avg = item.avgGap === null ? '--' : formatBoardCompactGap(item.avgGap);
    const meta = item.avgGap === null
      ? 'No completed bets'
      : `${avg} avg · ${item.count} ${countWord(item.count, 'bet', 'bets')}`;
    return `
    <button class="legend-item closeness-legend-item${activePlayer === item.name ? ' on' : ''}" type="button" data-closeness-player="${esc(item.name)}">
      <div class="legend-swatch" style="background:${color};"></div>
      <div class="legend-name">${esc(item.name)}</div>
      <div class="legend-meta">${esc(meta)}</div>
    </button>`;
  }).join('');

  return `
  <div class="closeness-wrap">
    <div class="closeness-graph">
      <button class="accuracy-zoom-reset" type="button" data-accuracy-zoom-reset aria-label="Reset Accuracy zoom">1× · Reset</button>
      <div class="accuracy-active-name" style="color:${colorOf(activePlayer)};">${esc(activePlayer)}</div>
      <div class="closeness-y-axis"></div>
      <div class="closeness-y-label">Distance from wrap</div>
      ${yTicks}
      <div class="closeness-viewport">
        <div class="closeness-timeline">
          <div class="closeness-x-axis"></div>
          ${dayTicks}
          <div class="closeness-x-label">Days</div>
          <svg class="closeness-lines" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${lineSvg}</svg>
          ${markerHtml}
        </div>
      </div>
    </div>
    ${orderControl}
    <div class="board-legend">${legendHtml}</div>
  </div>`;
}


// First Take of the Day is an independent morning game. Its points are
// derived from saved results, never added directly to the mutable wrap scores.
function ftoStore() {
  if (!S.ftoDays || typeof S.ftoDays !== 'object' || Array.isArray(S.ftoDays)) S.ftoDays = {};
  return S.ftoDays;
}
function ftoDate(day=S.today) { return displayToISO(day?.date) || localDateISO(); }
function ftoGame(date=ftoDate()) { return ftoStore()[date] || null; }
function ftoTerritories(game) {
  const bets=[...(game?.bets||[])].filter(b=>isValidHM(b.time)).sort((a,b)=>toSec(a.time)-toSec(b.time));
  const groups=[];
  for(const bet of bets) {
    const sec=toSec(bet.time);
    if(groups.length && groups[groups.length-1].sec===sec) groups[groups.length-1].names.push(bet.name);
    else groups.push({sec,names:[bet.name]});
  }
  return groups.map((g,i)=>({names:g.names,
    start:i===0?g.sec-1800:Math.floor((groups[i-1].sec+g.sec)/2)+1,
    end:i===groups.length-1?g.sec+1800:Math.floor((g.sec+groups[i+1].sec)/2)}));
}
function ftoWinners(game) {
  if(!game?.result || !isValidHM(game.result)) return [];
  const actual=toSec(game.result);
  const territory=ftoTerritories(game).find(r=>actual>=r.start && actual<=r.end);
  return territory?.names||[];
}
function ftoRangeLabel(sec) {
  const normalized=((Math.floor(sec/60)%1440)+1440)%1440;
  return `${String(Math.floor(normalized/60)).padStart(2,'0')}:${String(normalized%60).padStart(2,'0')}`;
}
function ftoPointsFor(name) {
  return Object.values(ftoStore()).reduce((n,g)=>n+(ftoWinners(g).some(w=>nameKey(w)===nameKey(name))?1:0),0);
}
function ftoClosed(game, date) {
  if (!game) return false;
  if (game.result) return true;
  if (!isValidHM(game.closeAt)) return false;
  const today=localDateISO();
  return date<today || (date===today && nowSec()>=toSec(game.closeAt));
}
function ftoRows(game) {
  const winners=new Set(ftoWinners(game).map(nameKey));
  const territories=ftoTerritories(game);
  return [...(game?.bets||[])].sort((a,b)=>a.time.localeCompare(b.time)).map(b=>{
    const territory=territories.find(t=>t.names.some(n=>nameKey(n)===nameKey(b.name)));
    const range=territory?`${ftoRangeLabel(territory.start)} – ${ftoRangeLabel(territory.end)}`:'';
    return `<div class="fto-bet-row"><div class="fto-bet-name"><strong>${esc(b.name)}</strong>${range?`<span class="fto-bet-range">${esc(range)}</span>`:''}</div><span class="fto-bet-time">${esc(b.time)}</span>${game.result?`<span class="fto-result">${winners.has(nameKey(b.name))?'+1 PT':''}</span>`:''}</div>`;
  }).join('');
}
function renderFTOCard(date=ftoDate(), admin=false) {
  const g=ftoGame(date), closed=ftoClosed(g,date);
  const isAdmin=admin && IS_ADMIN && !!currentUser;
  const status=g?.result?'COMPLETE':closed?'CLOSED':g?'OPEN':'NOT ACTIVE';
  const rows=g?.bets?.length?`<div class="fto-bets">${ftoRows(g)}</div>`:'<p class="mono dim">No predictions yet</p>';
  return `<div class="card fto-card">
    <div class="fto-heading"><div class="card-lbl">FIRST TAKE OF THE DAY</div><span class="fto-status">${status}</span></div>
    ${g?`<p class="mono dim">Betting closes at ${esc(g.closeAt||'--:--')} · ${g.bets?.length||0} predictions</p>`:'<p class="mono dim">Morning prediction game</p>'}
    ${g?.result?`<div class="fto-actual">First take <strong>${esc(g.result)}</strong></div><p class="mono dim">Winner: ${ftoWinners(g).map(esc).join(', ')||'None'} · 1 point each</p>`:''}
    ${isAdmin && !g?.result?`<div class="fto-controls"><label class="mono dim" for="fto-close">Betting closes</label><input id="fto-close" class="admin-time-input" inputmode="numeric" placeholder="HH:MM" value="${esc(g?.closeAt||'')}"><button class="btn btn-p" data-fto-action="close" data-fto-date="${esc(date)}">${g?'Update closing time':'Activate First Take of the Day'}</button></div>`:''}
    ${g?`<button type="button" class="fto-time-pill ${isAdmin&&!g.result?'fto-time-pill-admin':''}" ${isAdmin&&!g.result?'data-fto-action="pill" data-fto-date="'+esc(date)+'"':''} ${isAdmin&&!g.result?'title="Tap to record first take"':''}>${esc(g.result||'--:--')}<small>${g.result?'FIRST TAKE':'FIRST TAKE · '+(isAdmin?'TAP TO RECORD':'AWAITING')}</small></button>`:''}
    ${g?rows:''}
    ${isAdmin && g && !g.result?`<div class="fto-import-panel"><label class="mono dim" for="fto-import">Predictions (Name HH:MM, one per line)</label><textarea id="fto-import" rows="4" placeholder="Greta 08:42&#10;Giulia 08:47"></textarea><button class="btn" data-fto-action="import" data-fto-date="${esc(date)}">Import predictions</button></div>`:''}
  </div>`;
}
function renderFTOStats() {
  const games=Object.entries(ftoStore()).filter(([,g])=>g?.result);
  const names=getSortedPlayerRoster().filter(p=>p.active!==false);
  return `<div class="card fto-stats-card"><div class="card-lbl">FIRST TAKE OF THE DAY</div>
  <p class="mono dim">${games.length} completed days · 1 point per winning prediction, including exact guesses</p>
  ${names.map(p=>{
    const bets=games.filter(([,g])=>(g.bets||[]).some(b=>nameKey(b.name)===nameKey(p.name)));
    const errors=bets.map(([,g])=>Math.abs(toSec(g.bets.find(b=>nameKey(b.name)===nameKey(p.name)).time)-toSec(g.result))/60);
    const avg=errors.length?(errors.reduce((a,b)=>a+b,0)/errors.length).toFixed(1):'—';
    const exact=errors.filter(e=>e===0).length;
    return `<div class="fto-stats-row"><strong>${esc(p.name)}</strong><span>${bets.length} played</span><span>${ftoPointsFor(p.name)} wins</span><span>${avg} min avg.</span><span>${exact} exact</span></div>`;
  }).join('')||'<div class="empty">No players yet</div>'}</div>`;
}
// Inject the layout CSS from app.js so this can be installed as a single-file update.
(function installTodayModeStyles(){
  if(document.getElementById('today-mode-styles')) return;
  const style=document.createElement('style');
  style.id='today-mode-styles';
  style.textContent='/* TODAY full-width WRAP / FTO selector */\n.today-mode-layout{width:100%;min-width:0;display:flex;flex-direction:column;gap:12px}\n.today-mode-tabs{display:flex;gap:8px;width:100%;align-items:center}\n.today-mode-pill{flex:1;min-width:0;appearance:none;border:1px solid var(--border,rgba(127,127,127,.3));border-radius:999px;background:transparent;color:inherit;font:inherit;font-weight:700;letter-spacing:.05em;padding:11px 16px;cursor:pointer;transition:background .15s,border-color .15s}\n.today-mode-pill.is-active{background:var(--accent,#5b9e73);border-color:var(--accent,#5b9e73);color:#fff}\n.today-mode-pill:focus-visible{outline:2px solid currentColor;outline-offset:2px}\n.today-mode-layout>[data-today-panel]{width:100%;min-width:0}\n.today-mode-layout>[data-today-panel][hidden]{display:none!important}\n.today-mode-layout .fto-card{max-height:none;overflow:visible;width:100%}\n.today-mode-layout .fto-bets{max-height:none}\n';
  document.head.appendChild(style);
})();
// Keep the selected TODAY mode when navigating away and back.
let _todayGameMode = 'wrap';
function mountFTOSections() {
  if(!S.today) return;
  document.querySelectorAll('.sec[data-view="today"]').forEach(sec=>{
    const game=ftoGame(ftoDate());
    const admin=IS_ADMIN && !!currentUser;
    if(!game && !admin) return;
    const host=document.createElement('div');
    host.className='fto-section-host';
    host.innerHTML=renderFTOCard(ftoDate(),IS_ADMIN);
    if(game) {
      const layout=document.createElement('div');
      layout.className='today-mode-layout';
      const tabs=document.createElement('div');
      tabs.className='today-mode-tabs';
      tabs.setAttribute('role','tablist');
      tabs.setAttribute('aria-label','Today game');
      tabs.innerHTML=`<button type="button" class="today-mode-pill" data-today-mode="wrap" role="tab">WRAP</button><button type="button" class="today-mode-pill" data-today-mode="fto" role="tab">FTO</button>`;
      const wrap=document.createElement('div');
      wrap.className='today-wrap-panel';
      while(sec.firstChild) wrap.appendChild(sec.firstChild);
      wrap.setAttribute('data-today-panel','wrap');
      host.setAttribute('data-today-panel','fto');
      layout.append(tabs,wrap,host);
      sec.appendChild(layout);
      setTodayGameMode(sec,_todayGameMode);
    } else {
      // Inactive FTO is visible only to admins, without changing the original WRAP layout.
      sec.appendChild(host);
    }
  });
  document.querySelectorAll('.sec[data-view="history"]').forEach(sec=>{
    const games=Object.entries(ftoStore()).filter(([,g])=>g?.result).sort((a,b)=>b[0].localeCompare(a[0]));
    if(!games.length) return;
    const host=document.createElement('div');host.className='fto-history-host';
    host.innerHTML=`<div class="card"><div class="card-lbl">FIRST TAKE OF THE DAY · HISTORY</div>${games.map(([date,g])=>`<div class="fto-history-row"><strong>${esc(date)}</strong><span>${esc(g.result)}</span><span>${ftoWinners(g).map(esc).join(', ')||'No winner'}</span></div>`).join('')}</div>`;
    sec.prepend(host);
  });
}
function setTodayGameMode(sec, mode) {
  if(!sec?.querySelector('.today-mode-layout')) return;
  _todayGameMode=mode==='fto'?'fto':'wrap';
  sec.querySelectorAll('[data-today-mode]').forEach(btn=>{
    const selected=btn.dataset.todayMode===_todayGameMode;
    btn.classList.toggle('is-active',selected);
    btn.setAttribute('aria-selected',String(selected));
    btn.tabIndex=selected?0:-1;
  });
  sec.querySelectorAll('[data-today-panel]').forEach(panel=>{
    panel.hidden=panel.dataset.todayPanel!==_todayGameMode;
  });
}
document.addEventListener('click',event=>{
  const pill=event.target.closest('[data-today-mode]');
  if(!pill) return;
  const sec=pill.closest('.sec[data-view="today"]');
  if(!sec) return;
  setTodayGameMode(sec,pill.dataset.todayMode);
});
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-fto-action]');
  if (!button || !IS_ADMIN || !currentUser || !S.today) return;
  const action=button.dataset.ftoAction;
  const date=button.dataset.ftoDate;
  if (date!==ftoDate()) return;
  const store=ftoStore();
  const game=store[date];
  if (action==='pill') {
    if(!game || game.result) return;
    const value=prompt('First Take of the Day · actual first take (HH:MM)');
    if(value===null) return;
    const normalized=value.trim().replace('.',':');
    if(!isValidHM(normalized)) return toast('Enter a valid HH:MM first take','err');
    if(!ftoClosed(game,date)) return toast('Wait until betting closes','err');
    if(!game.bets?.length) return toast('Import predictions first','err');
    if(!confirm(`Confirm first take at ${normalized}? This awards 1 point to the winner(s) within the winning range.`)) return;
    store[date]={...game,result:normalized};
  } else if (action==='close') {
    if (game?.result) return;
    const value=document.getElementById('fto-close')?.value.trim().replace('.',':');
    if (!isValidHM(value)) return toast('Enter a valid HH:MM closing time','err');
    if (date===localDateISO() && toSec(value)<=nowSec() && !game) return toast('Closing time must be in the future','err');
    store[date]={...(game||{}),closeAt:value,bets:game?.bets||[]};
  } else if (action==='import') {
    if (!game || game.result) return toast('First Take of the Day result is already confirmed','err');
    const lines=(document.getElementById('fto-import')?.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
    const parsed=[];
    for(const line of lines) {
      const match=line.match(/^(.+?)\s+(\d{1,2})[:.](\d{2})$/);
      if(!match) return toast(`Invalid prediction: ${line}`,'err');
      const name=match[1].trim(),time=match[2].padStart(2,'0')+':'+match[3];
      if(!isValidHM(time)) return toast(`Invalid time: ${line}`,'err');
      if(!S.playerRoster.some(p=>nameKey(p.name)===nameKey(name))) return toast(`Unknown player: ${name}`,'err');
      if(parsed.some(p=>nameKey(p.name)===nameKey(name))) return toast(`Duplicate player: ${name}`,'err');
      parsed.push({name,time});
    }
    if (!parsed.length) return toast('Paste at least one prediction','err');
    store[date]={...game,bets:parsed};
  } else if(action==='result') {
    if (!game) return;
    const value=document.getElementById('fto-result')?.value.trim().replace('.',':');
    if(!isValidHM(value)) return toast('Enter a valid first take time','err');
    if(!ftoClosed(game,date)) return toast('Wait until betting closes','err');
    if(!game.bets?.length) return toast('Import predictions first','err');
    if(!confirm(`Confirm first take at ${value}? This awards 1 point to each closest prediction.`)) return;
    store[date]={...game,result:value};
  } else return;
  if(await saveS()) render();
});

function getStandingsEntries() {
  const standingsPlayers = getSortedPlayerRoster().map(player => ({
    player,
    score: (Number(S.scores[player.name]) || 0) + ftoPointsFor(player.name),
    wins: getBoardPlayerStats(player.name).wins
  })).sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    if (b.wins !== a.wins) return b.wins - a.wins;
    return String(a.player.name || '').localeCompare(String(b.player.name || ''));
  });
  let previousRank = null;
  let previousScore = null;

  return standingsPlayers.map((entry, i) => {
    if (entry.score !== previousScore) {
      previousRank = i + 1;
    }

    const rank = previousRank;
    previousScore = entry.score;

    return { ...entry, rank };
  });
}

// Consecutive missed completed shooting days (not calendar days).
// Multiple units on the same date count as a single shooting day.
function getPlayerMissedGameStreak(playerName) {
  const daysByDate = new Map();
  for (const day of (S.days || [])) {
    if (!day?.wrapTime) continue;
    const date = displayToISO(day.date);
    if (!date) continue;
    if (!daysByDate.has(date)) daysByDate.set(date, new Set());
    for (const guess of (day.guesses || [])) {
      if (guess.time) daysByDate.get(date).add(nameKey(guess.name));
    }
  }
  let missed = 0;
  for (const date of [...daysByDate.keys()].sort().reverse()) {
    if (daysByDate.get(date).has(nameKey(playerName))) break;
    missed++;
  }
  return missed;
}

// The closest non-winning occupied time slots directly before and after
// the winning slot. Multiple players sharing a slot are counted separately.
function getNearMissLeaderboard() {
  const completed = getHistoryEntries().filter(day => day && day.wrapTime);
  const minGames = 1;
  const players = getSortedPlayerRoster().filter(p => p.active !== false);
  const rows = players.map(player => {
    const key = nameKey(player.name);
    let played = 0, nearMisses = 0, wins = 0;
    for (const day of completed) {
      const guesses = (day.guesses || []).filter(g => g && g.time);
      const own = guesses.find(g => nameKey(g.name) === key);
      if (!own) continue;
      played++;
      if (didPlayerWinDay(player.name, day)) { wins++; continue; }
      if (day.noWinner) continue;
      const winningNames = (day.winners || []).map(w => nameKey(w.name));
      if (!winningNames.length && day.winner) winningNames.push(nameKey(day.winner));
      const winningTimes = guesses.filter(g => winningNames.includes(nameKey(g.name))).map(g => toSec(g.time));
      if (!winningTimes.length) continue;
      const slots = [...new Set(guesses.map(g => toSec(g.time)))].sort((a,b) => a-b);
      const ownTime = toSec(own.time);
      const adjacent = winningTimes.some(t => {
        const idx = slots.indexOf(t);
        return idx >= 0 && (slots[idx-1] === ownTime || slots[idx+1] === ownTime);
      });
      if (adjacent) nearMisses++;
    }
    return {name:player.name, played, nearMisses, wins};
  }).filter(row => row.wins === 0 && row.played >= minGames && row.played > 0);
  return {completed:completed.length, minGames, rows:rows.sort((a,b) => b.nearMisses-a.nearMisses || b.played-a.played || a.name.localeCompare(b.name))};
}

function renderNearMissLeaderboard() {
  const {completed,minGames,rows} = getNearMissLeaderboard();
  return `<div class="card board-fixed-card near-miss-card">
    <div class="card-lbl">SO CLOSE</div>
    <h3>Most near misses without a win</h3>
    <p class="mono dim">Adjacent time slots to the daily winner · At least one game played · Never won</p>
    ${rows.length ? `<div class="near-miss-list">${rows.map((row,i)=>`<div class="near-miss-row"><span class="near-miss-rank">${i+1}</span><strong>${esc(row.name)}</strong><span class="mono dim">${row.played} played</span><span class="accent"><strong>${row.nearMisses}</strong> near misses</span></div>`).join('')}</div>` : '<div class="empty">No eligible players yet</div>'}
  </div>`;
}

function renderGameStats() {
  const pl = getSortedPlayerRoster().filter(p => p.active !== false);
  const options = [['pie','PIE CHART'],['accuracy','ACCURACY'],['near','NEAR MISSES'],['fto','FIRST TAKE OF THE DAY']];
  let content;
  if (_statsView === 'fto') {
    content = renderFTOStats();
  } else if (_statsView === 'accuracy') {
    content = `<div class="card board-fixed-card" id="game-stats-accuracy"><div class="card-lbl">ACCURACY</div>${pl.length ? renderBoardCloseness(pl) : '<div class="empty">No players yet</div>'}</div>`;
  } else if (_statsView === 'near') {
    content = renderNearMissLeaderboard();
  } else {
    content = `<div class="card board-fixed-card"><div class="card-lbl">PIE CHART</div>${pl.length ? renderBoardPie(pl) : '<div class="empty">No players yet</div>'}</div>`;
  }
  return `<div class="game-stats-page">
    <nav class="stats-subnav" aria-label="Statistics">
      ${options.map(([key,label]) => `<button type="button" class="stats-subnav-btn${_statsView===key?' on':''}" data-stats-view="${key}" aria-pressed="${_statsView===key}">${label}</button>`).join('')}
    </nav>
    <div class="stats-subview">${content}</div>
  </div>`;
}

// Delegated event listener works for both public and admin views, including
// when the app refreshes its markup after a Firebase update.
document.addEventListener('click', event => {
  const button = event.target.closest('[data-stats-view]');
  if (!button) return;
  const view = button.dataset.statsView;
  if (!['pie','accuracy','near','fto'].includes(view) || view === _statsView) return;
  _statsView = view;
  document.querySelectorAll('.sec[data-view="stats"]').forEach(section => {
    section.innerHTML = renderGameStats();
  });
});

function renderBoard(view='list') {
  const pl = getSortedPlayerRoster();
  if (!pl.length) return '<div class="empty">No players yet</div>';
  const toolbar = '';
  const standingsRows = getStandingsEntries().map((entry, i)=>{
  const { player: p, score, wins, rank } = entry;
  const openKey = `${i}:${p.name}`;
  const isOpen = _openBoardPlayer === openKey;
  const medalRankClass = [1, 2, 3].includes(rank) ? ` board-rank-${rank}` : '';
  const missedDays = getPlayerMissedGameStreak(p.name);
  const danger = p.active !== false && missedDays >= 3;
  return `<div class="board-player${isOpen ? ' open' : ''}${danger ? ' board-player-danger' : ''}">
    <div class="board-row">
      <div class="board-rank${medalRankClass}">${rank}</div>
      <button class="board-player-name" type="button" data-board-player="${esc(openKey)}" title="${esc(p.name)}"><span class="board-player-name-text">${esc(p.name)}</span>${danger ? `<span class="danger-label" title="${missedDays} consecutive shooting days without a bet"><span aria-hidden="true">⚠️</span> ${missedDays}</span>` : ''}</button>
      <div class="board-player-wins">${wins} ${countWord(wins, 'game', 'games')} won</div>
      <div class="board-player-points accent"><strong>${score}</strong><span class="mono dim">${countWord(score, 'pt', 'pts')}</span></div>
    </div>
    ${isOpen ? renderBoardPlayerStats(p.name) : ''}
  </div>`;
}).join('');
  const activePlayerCount =
    pl.filter(player => player.active !== false).length;

  return `<div class="card board-fixed-card board-standings-card">${toolbar}
    <div class="standings-player-count">${activePlayerCount} ${countWord(
      activePlayerCount,
      CUSTOM_UI_TEXT.playerCountSingular,
      CUSTOM_UI_TEXT.playerCountPlural
    )}</div>
    <div class="standings-scroll-list">${standingsRows}</div>
  </div>`;
}

function countWord(value, singular, plural) {
  return Math.abs(Number(value)) === 1 ? singular : plural;
}

function formatBoardGap(totalSec) {
  const sec = Math.max(0, Math.round(totalSec));
  const hour = Math.floor(sec / 3600);
  const min = Math.floor((sec % 3600) / 60);
  const rest = sec % 60;
  const parts = [];
  if (hour) parts.push(`${hour} ${countWord(hour, 'hour', 'hours')}`);
  if (min) parts.push(`${min} ${countWord(min, 'min', 'min')}`);
  if (rest) parts.push(`${pad(rest)} ${countWord(rest, 'sec', 'sec')}`);
  return parts.join(', ') || '0 sec';
}

function formatOfficialWrapOffset(offset) {
  if (!offset) return 'Winner';
  if (offset.direction === 'exact' || offset.distance === 0) return 'Exact bet';
  return `${formatBoardGap(offset.distance)} ${offset.direction} official wrap`;
}

function formatBoardCompactGap(totalSec) {
  const sec = Math.max(0, Math.round(totalSec));
  if (sec < 60) return `${sec}s`;
  if (sec < 3600) {
    const min = Math.floor(sec / 60);
    const rest = sec % 60;
    return `${min}m${rest ? `${pad(rest)}s` : ''}`;
  }
  const hour = Math.floor(sec / 3600);
  const min = Math.floor((sec % 3600) / 60);
  return `${hour}h${min ? `${pad(min)}m` : ''}`;
}

function formatBoardExactCompactGap(totalSec) {
  const sec = Math.max(0, Math.round(totalSec));
  const hour = Math.floor(sec / 3600);
  const min = Math.floor((sec % 3600) / 60);
  const rest = sec % 60;
  const parts = [];
  if (hour) parts.push(`${hour}h`);
  if (min) parts.push(`${hour ? pad(min) : min}m`);
  if (rest || !parts.length) parts.push(`${hour || min ? pad(rest) : rest}s`);
  return parts.join('');
}

function wrongTerritoryGap(name, day) {

  if (!day?.wrapTime || !day.guesses?.length) return null;

  const wrapSec = wrapTimelineSec(day.wrapTime, day);

  const slices = boundaries(day.guesses, day, wrapSec);

  const slice = slices.find(s => s.names.includes(name));

  if (!slice || (wrapSec >= slice.start && wrapSec <= slice.end)) return null;

  return wrapSec < slice.start ? slice.start - wrapSec : wrapSec - slice.end;

}

function openHistoryDay(date, unit = 'main') {
  const isoDate = displayToISO(date);
  const unitKey = unit || 'main';

  const row = [...document.querySelectorAll('[data-history-row]')].find(el =>
    displayToISO(el.dataset.historyDate) === isoDate &&
    (el.dataset.historyUnit || 'main') === unitKey
  );
  if (!row) return false;
  setTimeout(() => {
    row.classList.add('open');
    setMainTab('history');
    requestAnimationFrame(() => {
      const history = row.closest('.sec[data-view="history"]');
      if (!history) return;
      row.classList.add('open');
      const rowTop = row.offsetTop - history.offsetTop;
      history.scrollTo({ top: Math.max(0, rowTop - 12), behavior: 'smooth' });
    });
  }, 0);
  return true;
}

function openHistoryHash() {
  const prefix = '#history-';
  if (!location.hash.startsWith(prefix)) return;
  const date = decodeURIComponent(location.hash.slice(prefix.length));
  if (openHistoryDay(date)) {
    history.replaceState(null, '', location.pathname + location.search);
  }
}

function getBoardPlayerStats(name) {
  const completed = getHistoryEntries();
  let wins = 0;
  let exact = 0;
  let forgot = 0;
  let lastGap = null;
  let lastGuess = null;
  let lastDay = null;
  let closestWrongGap = null;
  let closestWrongDate = null;
  let closestWrongUnit = null;

  [...completed].reverse().forEach(day => {
    const winnerNames = day.winners ? day.winners.map(w => w.name) : (day.winner ? [day.winner] : []);
    const won = !day.noWinner && winnerNames.includes(name);
    if (won) {
      wins += 1;
      const exactGuess = day.guesses?.find(g => g.name === name);
      if (isExactBetForDay(exactGuess, day)) exact += 1;
    }

    const guess = day.guesses?.find(g => g.name === name);
    if (guess && !guess.time) forgot += 1;
    if (guess?.time && day.wrapTime) {
      const gap = betMinuteDistanceFromWrapSec(guess, day);
      if (gap === null) return;
      if (lastGap === null) {
        lastGap = gap;
        lastGuess = guess;
        lastDay = day;
      }
      const wrongGap = wrongTerritoryGap(name, day);
      if (wrongGap !== null && (closestWrongGap === null || wrongGap < closestWrongGap)) {
        closestWrongGap = wrongGap;
        closestWrongDate = day.date || null;
        closestWrongUnit = day.unit || 'main';
      }
    }
  });

  return {
    wins,
    exact,
    forgot,
    days: completed.length,
    rate: completed.length ? `${Math.round((wins / completed.length) * 100)}%` : '0%',
    lastGap,
    lastGuess,
    lastDay,
    closestWrongGap,
    closestWrongDate,
    closestWrongUnit
  };
}

function getBoardPlayerMultiUnitBonus(name) {
  const key = nameKey(name);
  let total = 0;

  Object.values(S.multiUnitBonuses || {}).forEach(dateRecord => {
    if (!dateRecord || typeof dateRecord !== 'object') return;

    const entry = dateRecord[key];

    if (
      entry &&
      entry.status === 'awarded' &&
      Number(entry.points) > 0
    ) {
      total += Number(entry.points);
    }
  });

  return total;
}

function getBoardPlayerLostPoints(name) {
  const key = nameKey(name);
  let total = 0;

  getHistoryEntries().forEach(day => {
    dayPenalties(day).forEach(penalty => {
      if (nameKey(penalty?.name) !== key) return;

      const points = Number(penalty?.points) || 0;

      if (points < 0) {
        total += Math.abs(points);
      }
    });
  });

  return total;
}

function renderBoardPlayerStats(name) {
  const stats = getBoardPlayerStats(name);

  const multiUnitBonus =
    getBoardPlayerMultiUnitBonus(name);

  const lostPoints =
    getBoardPlayerLostPoints(name);

  const lastOffset = stats.lastGuess && stats.lastDay ? betMinuteOffsetFromWrap(stats.lastGuess, stats.lastDay) : null;
  const wrapGap = stats.lastGap === null
    ? 'No completed bets yet'
    : lastOffset?.direction === 'exact' || lastOffset?.distance === 0
      ? 'Last bet was <span class="accent">an exact bet</span>'
      : lastOffset?.direction
        ? `Last bet was <span class="accent">${formatBoardGap(lastOffset.distance)}</span> ${lastOffset.direction} official wrap`
        : `Last bet was <span class="accent">${formatBoardGap(stats.lastGap)}</span> from official wrap`;
  return `<div class="board-player-stats">
    <div class="board-player-gap">${wrapGap}</div>
    <div class="board-stat-grid">
      <div class="board-stat"><strong>${stats.wins}</strong><span>Total Wins</span></div>
      <div class="board-stat"><strong>${stats.exact}</strong><span>Exact Bet</span></div>
      <div class="board-stat"><strong>${multiUnitBonus ? `+${multiUnitBonus}` : 0}</strong><span>Multi Unit Bonus</span></div>
      <div class="board-stat"><strong>${lostPoints ? `-${lostPoints}` : 0}</strong><span>Lost Points</span></div>
    </div>
    <div class="board-win-rate">Win rate <span class="accent">${stats.rate}</span> - Won ${stats.wins} ${countWord(stats.wins, 'day', 'days')} out of ${stats.days}</div>
  </div>`;
}

function getHistoryEntries() {
  const all = [
    ...(S.days || [])
  ];

  const archivedKeys =
    new Set(
      all.map(day => {
        const date =
          displayToISO(day?.date);

        const unit =
          day?.unit || 'main';

        return `${date}-${unit}`;
      })
    );

  Object.values(
    getLiveGames()
  ).forEach(day => {
    if (!day?.wrapTime) {
      return;
    }

    const date =
      displayToISO(day.date);

    const unit =
      day.unit || 'main';

    const key =
      `${date}-${unit}`;

    /*
     * Evita di mostrare due volte la stessa
     * date+unit durante eventuali stati
     * transitori o dati legacy.
     */
    if (archivedKeys.has(key)) {
      return;
    }

    all.push(day);
    archivedKeys.add(key);
  });

  return all.sort((a, b) => {
    const dateA =
      getWrapDateISO(a) ||
      displayToISO(a?.date) ||
      '';

    const dateB =
      getWrapDateISO(b) ||
      displayToISO(b?.date) ||
      '';

    if (dateA !== dateB) {
      return dateA.localeCompare(dateB);
    }

    const timeA =
      a?.wrapTime && isValidHMS(a.wrapTime)
        ? toSec(a.wrapTime)
        : (
            a?.wrapTime && isValidHM(a.wrapTime)
              ? toSec(a.wrapTime)
              : 0
          );

    const timeB =
      b?.wrapTime && isValidHMS(b.wrapTime)
        ? toSec(b.wrapTime)
        : (
            b?.wrapTime && isValidHM(b.wrapTime)
              ? toSec(b.wrapTime)
              : 0
          );

    if (timeA !== timeB) {
      return timeA - timeB;
    }

    return String(a?.unit || 'main')
      .localeCompare(String(b?.unit || 'main'));
  });
}

function getLatestHistoryEntry() {
  const entries = getHistoryEntries();
  return entries.length
    ? entries[entries.length - 1]
    : null;
}

function deleteHistoryDayByDate(
  date,
  unit = 'main'
) {
  const isoDate =
    displayToISO(date);

  const unitKey =
    unit || 'main';

  const idx =
    S.days.findIndex(day =>
      displayToISO(day.date) === isoDate &&
      (day.unit || 'main') === unitKey
    );

  if (idx !== -1) {
    return {
      kind: 'history',
      idx
    };
  }

  const liveEntry =
    Object.entries(
      getLiveGames()
    ).find(([, day]) =>
      day &&
      day.wrapTime &&
      displayToISO(day.date) === isoDate &&
      (day.unit || 'main') === unitKey
    );

  if (liveEntry) {
    return {
      kind: 'live',
      unitKey: liveEntry[0]
    };
  }

  return null;
}

function findHistoryEntryByDate(
  date,
  unit = 'main'
) {
  const isoDate =
    displayToISO(date);

  const unitKey =
    unit || 'main';

  const historyIdx =
    S.days.findIndex(day =>
      displayToISO(day.date) === isoDate &&
      (day.unit || 'main') === unitKey
    );

  if (historyIdx !== -1) {
    return {
      kind: 'history',
      idx: historyIdx,
      day: S.days[historyIdx]
    };
  }

  const liveEntry =
    Object.entries(
      getLiveGames()
    ).find(([, day]) =>
      day &&
      day.wrapTime &&
      displayToISO(day.date) === isoDate &&
      (day.unit || 'main') === unitKey
    );

  if (liveEntry) {
    return {
      kind: 'live',
      idx: -1,
      unitKey: liveEntry[0],
      day: liveEntry[1]
    };
  }

  return null;
}

