async function updateHistoryWrapTime(
  date,
  unit = 'main',
  nextWrap,
  nextWrapDate = ''
) {
  if (!IS_ADMIN) return false;

  const target = findHistoryEntryByDate(date, unit);

  if (!target) {
    toast('History day not found', 'err');
    return false;
  }

  const currentWrap = target.day.wrapTime || '';
  const currentWrapDate =
    target.day.wrapDate ||
    inferBetDate(currentWrap, target.day);

  const normalizedWrap = normalizeHMSInput(nextWrap);
  const normalizedWrapDate = String(nextWrapDate || '').trim();

  if (!normalizedWrap) {
    toast('Enter wrap time', 'err');
    return false;
  }

  if (!isValidHMS(normalizedWrap)) {
    toast(
      'Use a valid wrap time (HH:MM or HH:MM:SS)',
      'err'
    );
    return false;
  }

  if (
    !normalizedWrapDate ||
    !dateFromISO(normalizedWrapDate)
  ) {
    toast('Use a valid wrap date', 'err');
    return false;
  }

  if (
    normalizedWrap === currentWrap &&
    normalizedWrapDate === currentWrapDate
  ) {
    return true;
  }

  const prevS = cloneState();

  const gameDate =
    displayToISO(target.day.date);

  const previousBonusRecord =
    getMultiUnitBonusRecord(gameDate);

  adjustCompletedDayScores(target.day, -1);

  /*
   * Save both parts of the official wrap before recalculating.
   * calcWinner() uses day.wrapDate to place the wrap on the
   * correct side of midnight.
   */
  target.day.wrapTime = normalizedWrap;
  target.day.wrapDate = normalizedWrapDate;

  const {
    winner,
    winners,
    points,
    noWinner,
    penalties
  } = calcWinner(
    target.day.guesses || [],
    normalizedWrap,
    target.day
  );

  target.day.winner = winner;
  target.day.winners = winners;
  target.day.points = points;
  target.day.noWinner = noWinner;
  target.day.penalties = penalties || [];

  adjustCompletedDayScores(target.day, 1);

  await reconcileMultiUnitBonusesAfterEdit(
    gameDate,
    previousBonusRecord
  );

  const saved = await saveS();

  if (!saved) {
    restoreAfterFailedSave(prevS);
    return false;
  }

  toast('Official wrap updated', 'ok');
  render();

  return true;
}

async function addHistoryPlayerBet(
  date,
  unit = 'main',
  name,
  betTime,
  betDate = ''
) {
  if (!IS_ADMIN) return false;
  const target = findHistoryEntryByDate(date, unit);
  if (!target) {
    toast('History day not found', 'err');
    return false;
  }
  const rosterPlayer = S.playerRoster.find(player => player.name === name);
  if (!rosterPlayer) {
    toast('Choose a roster player', 'err');
    return false;
  }
  const normalizedBet = normalizeHMInput(betTime);
  if (!normalizedBet) {
    toast('Enter bet time', 'err');
    return false;
  }
  if (!isValidHM(normalizedBet)) {
    toast('Use a valid bet time (HH:MM)', 'err');
    return false;
  }
  const normalizedDate = String(betDate || '').trim();
  if (normalizedDate && !dateFromISO(normalizedDate)) {
    toast('Use a valid bet date', 'err');
    return false;
  }
  const existingGuess = (target.day.guesses || []).find(g => nameKey(g.name) === nameKey(name));
  if (existingGuess?.time) {
    toast('Duplicate names', 'err');
    return false;
  }



  const prevS = cloneState();

  const gameDate =
    displayToISO(target.day.date);

  const previousBonusRecord =
    getMultiUnitBonusRecord(gameDate);

  adjustCompletedDayScores(target.day, -1);
  target.day.guesses = target.day.guesses || [];
  const nextGuess = existingGuess || { name };
  nextGuess.time = normalizedBet;
  nextGuess.date = normalizedDate || inferBetDate(normalizedBet, target.day);
  if (!existingGuess) target.day.guesses.push(nextGuess);
  const { winner, winners, points, noWinner, penalties } = calcWinner(target.day.guesses, target.day.wrapTime, target.day);
  target.day.winner = winner;
  target.day.winners = winners;
  target.day.points = points;
  target.day.noWinner = noWinner;
  target.day.penalties = penalties || [];
  adjustCompletedDayScores(target.day, 1);

  await reconcileMultiUnitBonusesAfterEdit(
    gameDate,
    previousBonusRecord
  );

  const saved = await saveS();
  if (!saved) { restoreAfterFailedSave(prevS); return false; }
  toast(`${name} bet added to ${getHistoryDayLabel(date)}`, 'ok');
  render();
  return true;
}

