function setCrazyDayForLiveGameDate(
  gameDate,
  crazyDay
) {
  const isoDate =
    displayToISO(gameDate);

  Object.values(
    getLiveGames()
  ).forEach(day => {
    if (
      !day ||
      displayToISO(day.date) !== isoDate
    ) {
      return;
    }

    if (crazyDay) {
      day.crazyDay =
        JSON.parse(
          JSON.stringify(crazyDay)
        );
    } else {
      delete day.crazyDay;
    }
  });
}

function readCrazyDayInput(id) {
  const value = Number(document.getElementById(id)?.value);
  return Number.isFinite(value) ? value : null;
}

function readCrazyDayPenaltyInput(id) {
  const value = readCrazyDayInput(id);
  return value === null ? null : -Math.abs(value);
}

async function saveCrazyDaySettings() {
  if (isStealTheDay(S.today) || isCrownDay(S.today)) {toast('Turn off Steal the Day or Crown Day before configuring Crazy Day','err');return;}
  if (
    !IS_ADMIN ||
    !S.today ||
    (S.today.unit || 'main') !== 'main' ||
    S.today.wrapTime ||
    S.today.guesses?.some(g => g.time)
  ) return false;
  const regularPoints = readCrazyDayInput('crazy-regular-points');
  const perfectPoints = readCrazyDayInput('crazy-perfect-points');
  const penaltyPoints = readCrazyDayPenaltyInput('crazy-penalty-points');
  const nearMissPenaltyPoints = readCrazyDayPenaltyInput('crazy-near-miss-points');
  if ([regularPoints, perfectPoints, penaltyPoints, nearMissPenaltyPoints].some(value => value === null)) {
    toast('Enter Crazy Day points', 'err');
    return false;
  }
  const prevS =
    cloneState();

  const gameDate =
    displayToISO(S.today.date);

  const crazyDay = {
    enabled: true,
    regularPoints,
    perfectPoints,
    penaltyPoints,
    nearMissPenaltyPoints
  };

  setCrazyDayForLiveGameDate(
    gameDate,
    crazyDay
  );

  _crazyDayPanelOpen = true;
  const saved = await saveS();
  if (!saved) { restoreAfterFailedSave(prevS); return false; }
  toast('Crazy Day saved', 'ok');
  render();
  return true;
}

async function clearCrazyDaySettings() {
  if (
    !IS_ADMIN ||
    !S.today ||
    (S.today.unit || 'main') !== 'main' ||
    S.today.wrapTime ||
    S.today.guesses?.some(g => g.time)
  ) return false;
  if (!S.today.crazyDay) {
    _crazyDayPanelOpen = false;
    render();
    return true;
  }
  const prevS =
    cloneState();

  const gameDate =
    displayToISO(S.today.date);

  setCrazyDayForLiveGameDate(
    gameDate,
    null
  );

  _crazyDayPanelOpen = false;
  const saved = await saveS();
  if (!saved) { restoreAfterFailedSave(prevS); return false; }
  toast('Crazy Day cleared', 'ok');
  render();
  return true;
}

async function handleAdminDialogAction(btn) {
  if (!IS_ADMIN || !currentUser) return;
  const action = btn.dataset.adminDialogAction;
  const date = btn.dataset.historyDate;
  const unit = btn.dataset.historyUnit || 'main';
  if (action === 'standings-export-save') {
    closeAdminDialog();
    await downloadStandingsExport();
    return;
  }
  if (action === 'history-wrap-open') {
    openHistoryWrapDialog(date, unit);
    return;
  }

  if (action === 'history-bet-players-open') {
    openHistoryBetPlayersDialog(date, unit);
    return;
  }

  if (action === 'history-bet-player-open') {
    openHistoryBetTimeDialog(
      date,
      unit,
      btn.dataset.historyPlayer
    );
    return;
  }

  if (action === 'history-delete-open') {
    openHistoryDeleteDialog(date, unit);
    return;
  }

  if (action === 'history-wrap-save') {
    const wrapDate = parseDateInput(
      document.getElementById('admin-history-wrap-date-input')?.value || ''
    );

    if (!wrapDate) {
      toast('Use a valid wrap date', 'err');
      return;
    }

    const updated = await updateHistoryWrapTime(
      date,
      unit,
      document.getElementById('admin-history-wrap-input')?.value,
      wrapDate
    );

    if (updated) closeAdminDialog();
    return;
  }

  if (action === 'history-bet-save') {
    const saved = await addHistoryPlayerBet(
      date,
      unit,
      btn.dataset.historyPlayer,
      document.getElementById('admin-history-bet-input')?.value,
      document.getElementById('admin-history-bet-date-input')?.value
    );

    if (saved) closeAdminDialog();
    return;
  }

  if (action === 'history-delete-confirm') {
    closeAdminDialog();
    deleteHistoryDay(date, unit, true);
    return;
  }
  if (action === 'today-wrap-manual') {
    openManualTodayWrapDialog();
    return;
  }
  if (action === 'roster-player-open') {
    openRosterPlayerDialog();
    return;
  }
  if (action === 'roster-player-save') {
    const saved = await addRosterPlayer(document.getElementById('admin-roster-player-input')?.value);
    if (saved) closeAdminDialog();
    return;
  }
  if (action === 'today-wrap-approve') {
    const saved = await confirmTodayWrap(
      btn.dataset.wrapTime,
      localDateISO()
    );

    if (saved) closeAdminDialog();
    return;
  }
  if (action === 'today-wrap-save') {
    const wrapDate = parseDateInput(
      document.getElementById('admin-today-wrap-date-input')?.value || ''
    );

    if (!wrapDate) {
      toast('Use a valid wrap date', 'err');
      return;
    }

    const saved = await confirmTodayWrap(
      document.getElementById('admin-today-wrap-input')?.value,
      wrapDate
    );

    if (saved) closeAdminDialog();
    return;
  }
  if (action === 'cancel-unit-confirm') {
    const cancelled =
      await cancelCurrentLiveUnit();

    if (cancelled) {
      closeAdminDialog();
    }

    return;
  }

  if (action === 'current-bet-save') {
    const saved = await addCurrentPlayerBet(
      btn.dataset.currentBetPlayer,
      document.getElementById('admin-current-bet-input')?.value,
      document.getElementById('admin-current-bet-date-input')?.value
    );
    if (saved) closeAdminDialog();
    return;
  }
  if (action === 'current-bet-update') {
    const saved = await updateCurrentPlayerBet(
      btn.dataset.currentBetPlayer,
      document.getElementById('admin-current-bet-input')?.value,
      document.getElementById('admin-current-bet-date-input')?.value
    );
    if (saved) closeAdminDialog();
    return;
  }
}

function getMultiUnitBonusCandidates(gameDate) {
  const isoDate =
    displayToISO(gameDate);

  /*
   * Una partita completata può trovarsi:
   *
   * - in History (S.days)
   * - ancora in liveGames dopo Official Wrap
   *
   * Dobbiamo considerare TUTTE le unità concluse,
   * non soltanto S.today.
   */
  const completedGames = [
    ...(S.days || []),
    ...Object.values(getLiveGames())
  ].filter(day =>
    day?.wrapTime &&
    displayToISO(day.date) === isoDate
  );

  /*
   * Protezione contro eventuali duplicati:
   * durante una transizione una stessa date+unit
   * non deve essere contata due volte.
   */
  const uniqueGames =
    new Map();

  completedGames.forEach(day => {
    const unit =
      day.unit || 'main';

    const key =
      `${isoDate}-${unit}`;

    if (!uniqueGames.has(key)) {
      uniqueGames.set(
        key,
        day
      );
    }
  });

  const winsByPlayer =
    new Map();

  uniqueGames.forEach(day => {
    if (day.noWinner) {
      return;
    }

    const winnerNames =
      Array.isArray(day.winners)
        ? day.winners
            .map(w => w.name)
            .filter(Boolean)
        : (
            day.winner
              ? [day.winner]
              : []
          );

    winnerNames.forEach(name => {
      const key =
        nameKey(name);

      if (!winsByPlayer.has(key)) {
        winsByPlayer.set(key, {
          player: name,
          wins: 0
        });
      }

      winsByPlayer.get(key).wins += 1;
    });
  });

  return [...winsByPlayer.values()]
    .filter(entry =>
      entry.wins >= 2
    )
    .sort((a, b) =>
      b.wins - a.wins ||
      a.player.localeCompare(
        b.player
      )
    );
}

function hasMultiUnitBonusDecision(gameDate) {
  const isoDate = displayToISO(gameDate);

  return Boolean(
    S.multiUnitBonuses &&
    typeof S.multiUnitBonuses === 'object' &&
    S.multiUnitBonuses[isoDate]
  );
}

function applyMultiUnitBonusDecisions(gameDate, decisions) {
  const isoDate = displayToISO(gameDate);

  if (
    !S.multiUnitBonuses ||
    typeof S.multiUnitBonuses !== 'object'
  ) {
    S.multiUnitBonuses = {};
  }

  const dateRecord = {};

  decisions.forEach(decision => {
    const points = Number(decision.points) || 0;

    dateRecord[nameKey(decision.player)] = {
      player: decision.player,
      wins: decision.wins,
      points,
      status: points > 0 ? 'awarded' : 'skipped'
    };

    if (points > 0) {
      applyScoreDelta(
        decision.player,
        points
      );
    }
  });

  S.multiUnitBonuses[isoDate] = dateRecord;
}

function requestMultiUnitBonusDecision(gameDate, candidates) {
  return new Promise(resolve => {
    const label =
      displayDate(gameDate) || gameDate;

    const rows = candidates.map((candidate, idx) => `
      <div class="admin-dialog-input-wrap">
        <label
          class="inp-lbl"
          for="multi-unit-bonus-${idx}"
        >
          ${esc(candidate.player)}
          · ${candidate.wins} Unit Wins
        </label>

        <input
          class="admin-dialog-wrap-input"
          type="number"
          id="multi-unit-bonus-${idx}"
          value="1"
          min="0"
          step="1"
          inputmode="numeric"
          aria-label="${esc(candidate.player)} bonus points"
        >
      </div>
    `).join('');

    openAdminDialog({
      title: 'Multi-Unit Bonus',
      copy:
        `${label} has player${candidates.length === 1 ? '' : 's'} ` +
        `with multiple unit wins. Choose bonus points. Use 0 for no bonus.`,
      showClose: false,
      body: `
        ${rows}

        <div class="admin-dialog-split">
          <button
            class="admin-dialog-action undo"
            type="button"
            data-multi-unit-bonus-skip
          >
            Skip All
          </button>

          <button
            class="admin-dialog-action approve"
            type="button"
            data-multi-unit-bonus-apply
          >
            Apply
          </button>
        </div>
      `
    });

    const modal =
      document.getElementById('admin-dialog-modal');

    modal
      ?.querySelector('[data-multi-unit-bonus-skip]')
      ?.addEventListener('click', () => {
        const decisions = candidates.map(candidate => ({
          player: candidate.player,
          wins: candidate.wins,
          points: 0
        }));

        closeAdminDialog();
        resolve(decisions);
      });

    modal
      ?.querySelector('[data-multi-unit-bonus-apply]')
      ?.addEventListener('click', () => {
        const decisions = [];

        for (let idx = 0; idx < candidates.length; idx++) {
          const candidate = candidates[idx];

          const raw =
            document.getElementById(
              `multi-unit-bonus-${idx}`
            )?.value;

          const points = Number(raw);

          if (
            !Number.isInteger(points) ||
            points < 0
          ) {
            toast(
              `Check ${candidate.player}'s bonus points`,
              'err'
            );
            return;
          }

          decisions.push({
            player: candidate.player,
            wins: candidate.wins,
            points
          });
        }

        closeAdminDialog();
        resolve(decisions);
      });
  });
}

function getMultiUnitBonusRecord(gameDate) {
  const isoDate = displayToISO(gameDate);

  const record =
    S.multiUnitBonuses &&
    typeof S.multiUnitBonuses === 'object'
      ? S.multiUnitBonuses[isoDate]
      : null;

  if (!record || typeof record !== 'object') {
    return {};
  }

  return JSON.parse(JSON.stringify(record));
}

function getAwardedMultiUnitBonuses(record) {
  if (!record || typeof record !== 'object') {
    return [];
  }

  return Object.values(record).filter(entry =>
    entry &&
    Number(entry.points) > 0
  );
}

function requestExistingMultiUnitBonusDecision(
  gameDate,
  bonus
) {
  return new Promise(resolve => {
    const label =
      displayDate(gameDate) || gameDate;

    const points =
      Number(bonus.points) || 0;

    openAdminDialog({
      title: 'Existing Multi-Unit Bonus',
      copy:
        `${bonus.player} currently has a +${points} bonus for ${label}. ` +
        `The results for this date have changed. Keep or remove this bonus?`,
      showClose: false,
      body: `
        <div class="admin-dialog-split">
          <button
            class="admin-dialog-action undo"
            type="button"
            data-existing-bonus-remove
          >
            Remove Bonus
          </button>

          <button
            class="admin-dialog-action approve"
            type="button"
            data-existing-bonus-keep
          >
            Keep +${points}
          </button>
        </div>
      `
    });

    const modal =
      document.getElementById('admin-dialog-modal');

    modal
      ?.querySelector('[data-existing-bonus-remove]')
      ?.addEventListener('click', () => {
        closeAdminDialog();
        resolve(false);
      });

    modal
      ?.querySelector('[data-existing-bonus-keep]')
      ?.addEventListener('click', () => {
        closeAdminDialog();
        resolve(true);
      });
  });
}

async function reconcileMultiUnitBonusesAfterEdit(
  gameDate,
  previousBonusRecord
) {
  const isoDate =
    displayToISO(gameDate);

  if (!isoDate) return;

  if (
    !S.multiUnitBonuses ||
    typeof S.multiUnitBonuses !== 'object'
  ) {
    S.multiUnitBonuses = {};
  }

  const oldRecord =
    previousBonusRecord &&
    typeof previousBonusRecord === 'object'
      ? previousBonusRecord
      : {};

  /*
   * First remove the old awarded bonus points from
   * the score. We will add back only the bonuses that
   * the admin decides to keep.
   */
  getAwardedMultiUnitBonuses(oldRecord)
    .forEach(entry => {
      applyScoreDelta(
        entry.player,
        -(Number(entry.points) || 0)
      );
    });

  const nextRecord = {};

  /*
   * Existing awarded bonuses are manual decisions.
   * Even if the player no longer qualifies after the
   * edit, the admin can explicitly keep the bonus.
   */
  for (
    const bonus of getAwardedMultiUnitBonuses(oldRecord)
  ) {
    const keep =
      await requestExistingMultiUnitBonusDecision(
        isoDate,
        bonus
      );

    if (!keep) continue;

    const points =
      Number(bonus.points) || 0;

    applyScoreDelta(
      bonus.player,
      points
    );

    nextRecord[nameKey(bonus.player)] = {
      player: bonus.player,
      wins: Number(bonus.wins) || 0,
      points,
      status: 'awarded'
    };
  }

  /*
   * Recalculate the multi-unit winners using the
   * edited results.
   */
  const candidates =
    getMultiUnitBonusCandidates(isoDate);

  /*
   * Anyone who now qualifies and does not already
   * have a kept bonus gets the normal bonus prompt.
   */
  const newCandidates =
    candidates.filter(candidate =>
      !nextRecord[nameKey(candidate.player)]
    );

  if (newCandidates.length > 0) {
    const decisions =
      await requestMultiUnitBonusDecision(
        isoDate,
        newCandidates
      );

    decisions.forEach(decision => {
      const points =
        Number(decision.points) || 0;

      if (points > 0) {
        applyScoreDelta(
          decision.player,
          points
        );
      }

      nextRecord[nameKey(decision.player)] = {
        player: decision.player,
        wins: decision.wins,
        points,
        status:
          points > 0
            ? 'awarded'
            : 'skipped'
      };
    });
  }

  /*
   * Refresh the number of wins stored for bonuses
   * that were kept.
   */
  candidates.forEach(candidate => {
    const key =
      nameKey(candidate.player);

    if (nextRecord[key]) {
      nextRecord[key].wins =
        candidate.wins;
    }
  });

  if (Object.keys(nextRecord).length > 0) {
    S.multiUnitBonuses[isoDate] =
      nextRecord;
  } else {
    delete S.multiUnitBonuses[isoDate];
  }
}

function applyScoreDelta(name, delta) {
  if (!name || !Number.isFinite(delta) || delta === 0) return;
  // Crazy Day penalties may bring a player below zero.
  // Never clamp scores to zero: 0 - 1 must be -1.
  const currentScore = Number(S.scores[name]) || 0;
  const nextScore = currentScore + delta;
  if (nextScore === 0) {
    delete S.scores[name];
  } else {
    S.scores[name] = nextScore;
  }
}

// Steal the Day: charge only confirmed non-voters, once per game.
function applyConfirmedStealNoBet(day, confirmedGuesses) {
  if (!isStealTheDay(day) || day.stealNoBetApplied === true) return;
  const betKeys = new Set((confirmedGuesses || [])
    .filter(g => g && g.name && g.time)
    .map(g => nameKey(g.name)));
  const missing = (S.playerRoster || [])
    .filter(p => p && p.name && p.active !== false && !betKeys.has(nameKey(p.name)))
    .map(p => ({name:p.name, points:-1, reason:'steal-no-bet'}));
  missing.forEach(p => applyScoreDelta(p.name, p.points));
  day.stealNoBetPenalties = missing;
  day.stealNoBetApplied = true;
}

function applyDayPenalties(day, direction) {
  (day?.penalties || []).forEach(penalty => {
    applyScoreDelta(penalty.name, direction * (Number(penalty.points) || 0));
  });
}

function adjustCompletedDayScores(day, direction) {
  const points = Number(day?.points) || 0;
  const names = points ? (day.winners ? day.winners.map(w => w.name) : (day.winner ? [day.winner] : [])) : [];
  names.forEach(name => {
    applyScoreDelta(name, direction * points);
  });
  applyDayPenalties(day, direction);
  (day?.stealNoBetPenalties || []).forEach(p => {
    applyScoreDelta(p.name, direction * (Number(p.points) || 0));
  });
}

function completedDayOutcome(day) {
  return {
    winner: day?.winner || '',
    winners: Array.isArray(day?.winners) ? day.winners.map(w => w.name).filter(Boolean) : (day?.winner ? [day.winner] : []),
    points: Number(day?.points) || 0,
    noWinner: Boolean(day?.noWinner),
    penalties: Array.isArray(day?.penalties) ? day.penalties.map(p => `${p.name}:${Number(p.points) || 0}:${p.reason || ''}`).sort() : []
  };
}

function outcomesMatch(a, b) {
  const aWinners = [...(a?.winners || [])].sort();
  const bWinners = [...(b?.winners || [])].sort();
  return Boolean(a?.noWinner) === Boolean(b?.noWinner)
    && Number(a?.points || 0) === Number(b?.points || 0)
    && String(a?.winner || '') === String(b?.winner || '')
    && aWinners.length === bWinners.length
    && aWinners.every((name, idx) => name === bWinners[idx])
    && (a?.penalties || []).length === (b?.penalties || []).length
    && (a?.penalties || []).every((item, idx) => item === (b?.penalties || [])[idx]);
}

function recalculateCompletedDay(day) {
  if (!day?.wrapTime) return;
  const { winner, winners, points, noWinner, penalties } = calcWinner(day.guesses || [], day.wrapTime, day);
  day.winner = winner;
  day.winners = winners;
  day.points = points;
  day.noWinner = noWinner;
  day.penalties = penalties || [];
}

function recalculateCompletedResultsForCurrentBoundaryRule() {
  let changed = false;

  const completedDays = [];

  const seenCompletedGames =
    new Set();

  [
    ...(S.days || []),
    ...Object.values(getLiveGames())
      .filter(day => day?.wrapTime)
  ].forEach(day => {
    if (!day?.wrapTime) return;

    const gameDate =
      displayToISO(day.date);

    const unit =
      day.unit || 'main';

    const key =
      `${gameDate}-${unit}`;

    if (seenCompletedGames.has(key)) {
      return;
    }

    seenCompletedGames.add(key);
    completedDays.push(day);
  });

  completedDays.forEach(day => {

    if (!day?.wrapTime) return;

    /*
     * Le giornate importate dallo storico sono già state
     * ricostruite e validate manualmente.
     *
     * Non devono essere ricalcolate automaticamente:
     * alcuni risultati storici dipendono dai secondi reali
     * del wrap o da eccezioni che non possono essere
     * ricostruite dai soli dati HH:MM.
     */
    if (
      day?.historicalImport?.source === 'migration-data.json'
    ) {
      return;
    }

    const previous =
      completedDayOutcome(day);

    const next =
      calcWinner(
        day.guesses || [],
        day.wrapTime,
        day
      );

    const nextOutcome = {
      winner: next.winner,
      winners: next.winners.map(w => w.name),
      points: next.points,
      noWinner: next.noWinner,
      penalties: (next.penalties || [])
        .map(
          p =>
            `${p.name}:${Number(p.points) || 0}:${p.reason || ''}`
        )
        .sort()
    };

    if (
      outcomesMatch(
        previous,
        nextOutcome
      )
    ) {
      return;
    }

    adjustCompletedDayScores(
      day,
      -1
    );

    day.winner =
      next.winner;

    day.winners =
      next.winners;

    day.points =
      next.points;

    day.noWinner =
      next.noWinner;

    day.penalties =
      next.penalties || [];

    adjustCompletedDayScores(
      day,
      1
    );

    changed = true;
  });

  return changed;
}

async function maybeSaveTerritoryRuleMigration() {
  if (LOCAL_TEST_MODE) return;

  if (
    !_territoryRuleMigrationPending ||
    _territoryRuleMigrationSaving ||
    !IS_ADMIN ||
    !currentUser
  ) {
    return;
  }
  _territoryRuleMigrationSaving = true;
  const saved = await saveS();
  _territoryRuleMigrationSaving = false;
  if (saved) {
    _territoryRuleMigrationPending = false;
    toast('Territories recalculated', 'ok');
    render();
  }
}

function removeAutoAddedPlayersFromDeletedDays(deletedDays) {
  const autoAddedKeys = new Set();
  deletedDays.forEach(day => {
    (day?.addedPlayers || []).forEach(name => autoAddedKeys.add(nameKey(name)));
  });
  if (!autoAddedKeys.size) return;

  const usedKeys = new Set();
  const remainingDays = [
    ...(S.days || []),
    ...Object.values(getLiveGames())
  ].filter(Boolean);
  remainingDays.forEach(day => {
    (day.guesses || []).forEach(guess => usedKeys.add(nameKey(guess.name)));
    (day.winners || []).forEach(winner => usedKeys.add(nameKey(winner.name)));
    if (day.winner) usedKeys.add(nameKey(day.winner));
  });

  S.playerRoster = S.playerRoster.filter(player => {
    const key = nameKey(player.name);
    if (!autoAddedKeys.has(key)) return true;
    if (usedKeys.has(key) || (Number(S.scores[player.name]) || 0) !== 0) return true;
    delete S.scores[player.name];
    return false;
  });
}

function getHistoryGameMatchCount(date, unit = 'main') {
  const isoDate = displayToISO(date);
  const unitKey = unit || 'main';

  return S.days.filter(day =>
    displayToISO(day.date) === isoDate &&
    (day.unit || 'main') === unitKey
  ).length;
}

async function deleteHistoryDay(
  date,
  unit = 'main',
  confirmed = false
) {
  const target =
    deleteHistoryDayByDate(
      date,
      unit
    );

  if (!target) {
    toast(
      'History game not found',
      'err'
    );
    return;
  }

  const label =
    displayDate(date) || date;

  const unitLabel =
    formatUnitLabel(unit);

  if (
    !confirmed &&
    !confirm(
      `Delete ${label} · ${unitLabel}? This cannot be undone.`
    )
  ) {
    return;
  }

  const prevS =
    cloneState();

  const prevActiveLiveUnit =
    _activeLiveUnit;

  const gameDate =
    displayToISO(date);

  const previousBonusRecord =
    getMultiUnitBonusRecord(
      gameDate
    );

  const day =
    target.kind === 'history'
      ? S.days[target.idx]
      : S.liveGames?.[
          target.unitKey
        ];

  if (!day) {
    toast(
      'History game not found',
      'err'
    );
    return;
  }

  /*
   * Roll back soltanto i punteggi
   * appartenenti alla partita eliminata.
   */
  adjustCompletedDayScores(
    day,
    -1
  );

  if (target.kind === 'history') {
    S.days.splice(
      target.idx,
      1
    );
  } else {
    /*
     * La partita è ancora dentro liveGames.
     * Eliminiamo esclusivamente la unità
     * richiesta, non quella selezionata.
     */
    if (
      isLiveGamesObject(
        S.liveGames
      )
    ) {
      delete S.liveGames[
        target.unitKey
      ];
    }

    /*
     * Se abbiamo eliminato proprio la unità
     * visualizzata nel browser, scegliamo
     * una delle unità live rimaste.
     *
     * Se invece era selezionata un'altra
     * unità, la lasciamo invariata.
     */
    if (
      _activeLiveUnit ===
        target.unitKey ||
      (S.today?.unit || 'main') ===
        (day.unit || target.unitKey)
    ) {
      _activeLiveUnit =
        null;

      const remainingUnits =
        Object.keys(
          getLiveGames()
        );

      if (remainingUnits.length) {
        const nextUnit =
          remainingUnits[0];

        _activeLiveUnit =
          nextUnit;

        S.activeUnit =
          nextUnit;

        S.today =
          S.liveGames[nextUnit];
      } else {
        S.activeUnit =
          'main';

        S.today =
          null;
      }
    }
  }

  removeAutoAddedPlayersFromDeletedDays(
    [day]
  );

  await reconcileMultiUnitBonusesAfterEdit(
    gameDate,
    previousBonusRecord
  );

  const saved =
    await saveS();

  if (!saved) {
    _activeLiveUnit =
      prevActiveLiveUnit;
    restoreAfterFailedSave(
      prevS
    );
    return;
  }

  /*
   * Riallineiamo esplicitamente la selezione
   * locale dopo il salvataggio.
   */
  if (
    target.kind === 'live'
  ) {
    const remainingUnits =
      Object.keys(
        getLiveGames()
      );

    if (
      _activeLiveUnit &&
      S.liveGames?.[_activeLiveUnit]
    ) {
      setActiveUnit(
        _activeLiveUnit
      );
    } else if (
      remainingUnits.length
    ) {
      setActiveUnit(
        remainingUnits[0]
      );
    }
  }

  toast(
    'History game deleted',
    'ok'
  );

  render();
}

function openCancelCurrentLiveUnitDialog() {
  if (
    !IS_ADMIN ||
    !S.today ||
    S.today.wrapTime
  ) {
    return;
  }

  const liveGames =
    getLiveGames();

  const currentUnit =
    S.today.unit || 'main';

  const liveUnits =
    Object.keys(liveGames);

  /*
   * Stessa protezione della funzione
   * che esegue realmente la cancellazione.
   */
  if (
    currentUnit === 'main' &&
    liveUnits.length !== 1
  ) {
    toast(
      'Main Unit can only be cancelled when it is the only live unit',
      'err'
    );
    return;
  }

  if (!liveGames[currentUnit]) {
    toast(
      'Live unit not found',
      'err'
    );
    return;
  }

  const unitLabel =
    formatUnitLabel(currentUnit);

  openAdminDialog({
    title: `Cancel ${unitLabel}`,
    copy: 'This will permanently remove this open unit and its bets.',
    showClose: false,
    body: `<div class="admin-dialog-split">
      <button
        class="admin-dialog-action undo"
        type="button"
        data-admin-dialog-close
      >Cancel</button>
      <button
        class="admin-dialog-action delete"
        type="button"
        data-admin-dialog-action="cancel-unit-confirm"
      >Confirm</button>
    </div>`
  });
}

async function cancelCurrentLiveUnit() {
  if (
    !IS_ADMIN ||
    !S.today ||
    S.today.wrapTime
  ) {
    return false;
  }

  const liveGames = getLiveGames();
  const currentGame = S.today;
  const currentUnit =
    currentGame.unit || 'main';
  const liveUnits =
    Object.keys(liveGames);

  /*
   * Main è cancellabile soltanto quando
   * è l'unica unità live.
   */
  if (
    currentUnit === 'main' &&
    liveUnits.length !== 1
  ) {
    toast(
      'Main Unit can only be cancelled when it is the only live unit',
      'err'
    );
    return false;
  }

  /*
   * Verifica difensiva:
   * la unità visualizzata deve esistere
   * realmente dentro liveGames.
   */
  if (!liveGames[currentUnit]) {
    toast(
      'Live unit not found',
      'err'
    );
    return false;
  }

  const unitLabel =
    formatUnitLabel(currentUnit);

  const prevS =
    cloneState();

  const prevActiveLiveUnit =
    _activeLiveUnit;

  /*
   * Cancel Unit NON modifica History,
   * scores, streaks, roster,
   * addedPlayers o bonus.
   *
   * Rimuove esclusivamente
   * la live unit aperta.
   */
  delete S.liveGames[currentUnit];

  if (_activeLiveUnit === currentUnit) {
    _activeLiveUnit = null;
  }

  const remainingUnits =
    Object.keys(getLiveGames());

  if (remainingUnits.length) {
    /*
     * Se Main esiste ancora,
     * torniamo sempre a Main.
     *
     * Altrimenti scegliamo una delle
     * unità live rimaste.
     */
    const nextUnit =
      S.liveGames.main
        ? 'main'
        : remainingUnits[0];

    _activeLiveUnit =
      nextUnit;

    S.activeUnit =
      nextUnit;

    S.today =
      S.liveGames[nextUnit];
  } else {
    /*
     * Questo caso è consentito soltanto
     * quando Main era l'unica unità live.
     */
    _activeLiveUnit =
      null;

    S.activeUnit =
      'main';

    S.today =
      null;
  }

  const saved =
    await saveS();

  if (!saved) {
    /*
     * Se Firebase non salva,
     * ripristiniamo integralmente
     * lo stato precedente.
     */
    _activeLiveUnit =
      prevActiveLiveUnit;

    restoreAfterFailedSave(
      prevS
    );

    return false;
  }

  /*
   * Riallineiamo la selezione locale
   * dopo il salvataggio.
   */
  if (
    _activeLiveUnit &&
    S.liveGames?.[_activeLiveUnit]
  ) {
    setActiveUnit(
      _activeLiveUnit
    );
  }

  toast(
    `${unitLabel} cancelled`,
    'ok'
  );

  render();

  return true;
}

async function archiveCurrentLiveUnit() {
  if (
    !IS_ADMIN ||
    !S.today ||
    !S.today.wrapTime
  ) {
    return false;
  }

  const prevS = cloneState();

  const prevActiveLiveUnit =
    _activeLiveUnit;

  const currentGame = S.today;
  const currentUnit =
    currentGame.unit || 'main';

  const currentDate =
    displayToISO(currentGame.date);

  /*
   * Aggiungiamo allo storico solo se non esiste
   * già la stessa combinazione gameDate + unit.
   */
  const alreadyArchived =
    (S.days || []).some(day =>
      displayToISO(day.date) === currentDate &&
      (day.unit || 'main') === currentUnit
    );

  // Same date and unit may occur multiple times; each completed game
  // is a distinct history record.
  S.days.push(JSON.parse(JSON.stringify(currentGame)));

  /*
   * Da questo momento la partita non è più una
   * live unit, ma rimane normalmente in History.
   */
  if (isLiveGamesObject(S.liveGames)) {
    delete S.liveGames[currentUnit];
  }

  if (_activeLiveUnit === currentUnit) {
    _activeLiveUnit = null;
  }

  const remainingUnits =
    Object.keys(getLiveGames());

  if (remainingUnits.length) {
    const nextUnit =
      remainingUnits[0];

    _activeLiveUnit =
      nextUnit;

    S.today =
      S.liveGames[nextUnit];
  } else {
    S.today = null;
  }

  const saved = await saveS();

  if (!saved) {
    _activeLiveUnit =
      prevActiveLiveUnit;

    restoreAfterFailedSave(prevS);
    return false;
  }

  if (remainingUnits.length) {
    setActiveUnit(
      remainingUnits[0]
    );
  }

  render();

  return true;
}

async function deleteCurrentDayAndMatchingHistory() {
  if (!IS_ADMIN || !S.today) return;

  const isoDate =
    displayToISO(S.today.date);

  const unit =
    S.today.unit || 'main';

  const label =
    displayDate(isoDate) || isoDate;

  const unitLabel =
    formatUnitLabel(unit);

  /*
   * Normalmente S.today non dovrebbe avere una copia
   * equivalente dentro S.days.
   *
   * Se però esiste per qualche motivo, rimuoviamo solo
   * quella con stessa data E stessa unità.
   */
  const matchingHistoryIndexes =
    S.days
      .map((day, idx) =>
        displayToISO(day.date) === isoDate &&
        (day.unit || 'main') === unit
          ? idx
          : -1
      )
      .filter(idx => idx !== -1);

  const confirmCopy =
    matchingHistoryIndexes.length
      ? `Delete ${label} · ${unitLabel} and its matching history entry? This cannot be undone.`
      : `Delete ${label} · ${unitLabel}? This cannot be undone.`;

  if (!confirm(confirmCopy)) {
    return;
  }

  const prevS =
    cloneState();

  const prevActiveLiveUnit =
    _activeLiveUnit;

  const previousBonusRecord =
    getMultiUnitBonusRecord(isoDate);

  const deletedDays = [
    S.today,
    ...matchingHistoryIndexes.map(
      idx => S.days[idx]
    )
  ];

  adjustCompletedDayScores(
    S.today,
    -1
  );

  matchingHistoryIndexes.forEach(
    idx =>
      adjustCompletedDayScores(
        S.days[idx],
        -1
      )
  );

  /*
   * Manteniamo tutte le altre unità
   * della stessa data.
   */
  S.days = S.days.filter(day =>
    !(
      displayToISO(day.date) === isoDate &&
      (day.unit || 'main') === unit
    )
  );

  /*
  * Eliminiamo esclusivamente la unità corrente.
  * Le altre partite live devono continuare a esistere.
  */
  if (isLiveGamesObject(S.liveGames)) {
    delete S.liveGames[unit];
  }

  /*
  * Se il browser stava visualizzando proprio questa unità,
  * dimentichiamo la selezione locale.
  */
  if (_activeLiveUnit === unit) {
    _activeLiveUnit = null;
  }

  /*
  * Passiamo automaticamente a un'altra eventuale
  * partita live.
  */
  const remainingLiveUnits =
    Object.keys(getLiveGames());

  if (remainingLiveUnits.length) {
    const nextActiveUnit =
      remainingLiveUnits[0];

    _activeLiveUnit =
      nextActiveUnit;

    S.activeUnit =
      nextActiveUnit;

    S.today =
      S.liveGames[nextActiveUnit];
  } else {
    S.activeUnit = 'main';
    S.today = null;
  }

  removeAutoAddedPlayersFromDeletedDays(
    deletedDays
  );

  await reconcileMultiUnitBonusesAfterEdit(
    isoDate,
    previousBonusRecord
  );

  const saved =
    await saveS();

  if (!saved) {
    _activeLiveUnit =
      prevActiveLiveUnit;
    restoreAfterFailedSave(prevS);
    return;
  }

  toast(
    'Current game deleted',
    'ok'
  );

  render();
}

function formatHistoryMobileUnitLabel(unit) {
  const units = [
    'main',
    'second',
    'third',
    'fourth',
    'fifth',
    'sixth',
    'seventh',
    'eighth',
    'ninth',
    'tenth'
  ];

  const unitKey = unit || 'main';
  const index = units.indexOf(unitKey);

  if (index !== -1) {
    return index === 0 ? 'MU' : `${index + 1}U`;
  }

  const match = String(unitKey).match(/^unit-(\d+)$/);
  if (match) return `${match[1]}U`;

  return formatUnitLabel(unitKey);
}

function renderHistory() {
  const all = getHistoryEntries();
  if (!all.length) return '<div class="tab-page-frame"><div class="empty">No completed days yet</div></div>';

  const historyRows = [...all].reverse().map((d, i) => {
    const num = all.length - i;
    const historyIndex = all.length - i - 1;
    const sg = sortedGuesses(d.guesses, d);
    const canManage = IS_ADMIN;
    const estWrapInfo = `<div class="hist-est-wrap">Estimated Wrap - <span>${esc(d.estWrap || '--:--')}</span></div>`;
    const historyDate = esc(d.date);
    const unitLabel = formatUnitLabel(d.unit);
    const historyUnit = esc(d.unit || 'main');
    const historyDetailsLabel =
      `${esc(displayDate(d.date) || d.date)} · ${esc(unitLabel)} Leaderboard`;
    const internalDayNumber =
      getInternalProjectDayNumberForDate(d.date);

    const dayLabel =
      internalDayNumber === null
        ? 'History Day'
        : displayDayLabel(internalDayNumber);
    const mobileUnitLabel = formatHistoryMobileUnitLabel(d.unit);
    const showHistoryUnit = new Set(all.filter(entry => entry.date === d.date).map(entry => entry.unit || 'main')).size > 1;
    const historyUnitTag = showHistoryUnit ?
      `<span class="hist-unit-tag"><span class="hist-unit-label-full">${esc(unitLabel)}</span><span class="hist-unit-label-mobile">${esc(mobileUnitLabel)}</span></span>` : '';
    const penaltiesByPlayer = dayPenaltyMap(d);
    const historyDayTag = canManage
      ? `<button
          class="hist-day-tag hist-day-edit"
          type="button"
          title="Edit ${dayLabel} · ${esc(unitLabel)}"
          aria-label="Edit ${dayLabel} · ${esc(unitLabel)}"
          data-history-edit="${historyDate}"
          data-history-unit="${historyUnit}"
        >${dayLabel}</button>`
      : `<span class="hist-day-tag">${dayLabel}</span>`;
    const historyShareTag = (className, content) => canManage
      ? `<button class="${className} hist-share-trigger" style="font-weight:bold" type="button" data-history-share-result="${historyIndex}">${content}</button>`
      : `<span class="${className}" style="font-weight:bold">${content}</span>`;
    
    if (d.noWinner) {
        const slices = boundaries(d.guesses, d);
        return `
        <div class="card hist-row"
             data-history-row
             data-history-date="${historyDate}"
             data-history-unit="${historyUnit}">
          <div class="hist-summary">
            <div class="hist-main-info">
              ${historyDayTag}
              ${historyUnitTag}
              ${historyShareTag('hist-title red', 'No Winner')}
            </div>
            <div class="hist-meta">
              <span class="accent mono hist-wrap-time">${esc(d.wrapTime)}</span>
              <span class="dim mono hist-points">+0pts</span>
              <span class="hist-arrow">▶</span>
            </div>
          </div>
          <div class="hist-details" data-history-details>
            <div class="hist-details-head">
              <div class="card-lbl">${historyDetailsLabel}</div>
              ${estWrapInfo}
            </div>
            ${sg.map(g => {
              const slice = g.time ? slices.find(s => s.names.includes(g.name)) : null;
              const prob  = g.time ? getWinProbability(g.name, d.guesses, d) : null;
              const penaltyPoints = penaltiesByPlayer.get(nameKey(g.name)) || 0;
              return `
              <div class="row${slice ? ' row-with-boundary' : ''}">
                <div class="row-name row-name-stack">
                  <div class="row-name-main"><span>${esc(g.name)}</span></div>
                  ${slice ? `<div class="row-boundary">${slice.startStr} → ${slice.endStr}</div>` : ''}
                </div>
                ${g.time ? `
                  <div class="badge b-prob">${prob.text}</div>
                  <div class="row-time">${esc(g.time)}</div>
                  <div class="badge ${penaltyPoints ? 'b-penalty' : 'b-out'}">${penaltyPoints ? compactSignedPoints(penaltyPoints) : '—'}</div>
                ` : penaltyPoints ? `
                  <div class="badge b-history-forgot">Forgot to bet</div>
                  <div class="badge b-penalty">${compactSignedPoints(penaltyPoints)}</div>
                ` : `<div class="badge b-missing">${CUSTOM_UI_TEXT.forgotBet}</div>`}
              </div>`;
            }).join('')}
          </div>
        </div>`;
      }
    
    const histNames = d.winners ? d.winners.map(w => w.name) : [d.winner];
    const histWinnerMarkup = histNames.length > 1
      ? histNames.map(name => `<span>${esc(name)}</span>`).join('')
      : esc(histNames[0] || '');
    const histWinnerClass = histNames.length > 1 ? 'hist-title hist-title-multi accent' : 'hist-title accent';
    const winnerBet = d.guesses.find(g => histNames.includes(g.name))?.time || '--:--';
    const slices = boundaries(d.guesses, d);
    
    return `
    <div class="card hist-row"
         data-history-row
         data-history-date="${historyDate}"
         data-history-unit="${historyUnit}">
      <div class="hist-summary">
        <div class="hist-main-info">
          ${historyDayTag}
          ${historyUnitTag}
          ${historyShareTag(histWinnerClass, histWinnerMarkup)}
          <span class="hist-bet mono dim" style="font-size:0.75rem">(${esc(winnerBet)})</span>
        </div>
        <div class="hist-meta">
          <span class="accent mono hist-wrap-time">${esc(d.wrapTime)}</span>
          <span class="dim mono hist-points">+${d.points}${countWord(d.points, 'pt', 'pts')}</span>
          <span class="hist-arrow">▶</span>
        </div>
      </div>
      <div class="hist-details" data-history-details>
        <div class="hist-details-head">
          <div class="card-lbl">${historyDetailsLabel}</div>
          ${estWrapInfo}
        </div>
        ${sg.map(g => {
          const isWinner = histNames.includes(g.name);
          const slice = g.time ? slices.find(s => s.names.includes(g.name)) : null;
          const prob  = g.time ? getWinProbability(g.name, d.guesses, d) : null;
          const penaltyPoints = penaltiesByPlayer.get(nameKey(g.name)) || 0;
          return `
          <div class="row${slice ? ' row-with-boundary' : ''}${isWinner ? ' golden-winner-row' : ''}">
            <div class="row-name row-name-stack${isWinner ? ' history-winner-name' : ''}">
              <div class="row-name-main"><span>${esc(g.name)}</span></div>
              ${slice ? `<div class="row-boundary">${slice.startStr} → ${slice.endStr}</div>` : ''}
            </div>
            ${g.time ? `
              <div class="badge b-prob">${prob.text}</div>
              <div class="row-time">${esc(g.time)}</div>
              <div class="badge ${isWinner ? 'b-win' : (penaltyPoints ? 'b-penalty' : 'b-out')}">
                ${isWinner ? `+${d.points}` : (penaltyPoints ? compactSignedPoints(penaltyPoints) : '—')}
              </div>
            ` : penaltyPoints ? `
              <div class="badge b-history-forgot">Forgot to bet</div>
              <div class="badge b-penalty">${compactSignedPoints(penaltyPoints)}</div>
            ` : `<div class="badge b-missing">${CUSTOM_UI_TEXT.forgotBet}</div>`}
          </div>`;
        }).join('')}
      </div>
    </div>`;
  }).join('');
  return `<div class="tab-page-frame">${historyRows}</div>`;
}


// Fight the Boss is an optional, one-use challenge per player per competition.
let _bossPanelOpen = false;
function bossConfig(day) {
  return day?.fightTheBoss?.enabled ? day.fightTheBoss : null;
}
function bossParticipants(day) {
  return Array.isArray(bossConfig(day)?.players) ? bossConfig(day).players : [];
}
function bossHasPlayed(name, excludeDay = null) {
  const key = nameKey(name);
  const days = [...getHistoryEntries(), ...Object.values(getLiveGames())];
  return days.some(day => day && day !== excludeDay && day !== S.today &&
    (day.wrapTime || (day.guesses || []).some(g => g.time)) &&
    bossParticipants(day).some(n => nameKey(n) === key));
}
function bossBetClosed(day) {
  if (day?.wrapTime) return true;
  if (!day?.betCloseAt || !isValidHM(day.betCloseAt)) return false;
  const remaining = betCloseDiffSec(day);
  return remaining !== null && remaining <= 0;
}
function bossBonuses(guesses, wrap, day) {
  const cfg = bossConfig(day);
  if (!cfg || !isValidHM(cfg.time) || !wrap) return [];
  const wrapSec = wrapTimelineSec(wrap, day);
  const bossDistance = Math.abs(alignClockSecToReference(cfg.time, wrapSec) - wrapSec);
  return bossParticipants(day).map(name => {
    const guess = guesses.find(g => nameKey(g.name) === nameKey(name));
    if (!guess?.time) return {name, points:-5, reason:'boss-loss'};
    const distance = Math.abs(betTimelineSec(guess, wrapSec) - wrapSec);
    return {name, points:distance < bossDistance ? 2 : -5,
      reason:distance < bossDistance ? 'boss-win' : 'boss-loss'};
  });
}
function bossTodayCard(day) {
  if (!bossConfig(day) || !bossParticipants(day).length) return '';
  return `<div class="card boss-time-card"><img class="boss-time-logo" src="imgs/totowrap-fight-the-boss.png" alt="TotoWrap Upgraded Fight the Boss" loading="lazy"><div class="card-lbl">⚔ BOSS WRAP TIME</div>
    <div class="boss-time-value mono" data-boss-time-value>${bossBetClosed(day) && isValidHM(bossConfig(day).time) ? esc(bossConfig(day).time) : '--:--'}</div>
    ${!bossBetClosed(day)?'<div class="mono dim boss-time-note">Revealed when betting closes</div>':''}
  </div>`;
}
function bossTodayTag(name, day) {
  return bossParticipants(day).some(n=>nameKey(n)===nameKey(name))
    ? '<div class="boss-player-tag">This player is fighting THE BOSS</div>' : '';
}
function renderBossSetupCard(day=S.today) {
  const cfg=bossConfig(day), enabled=!!cfg;
  const finished=!!day?.wrapTime;
  const names=getAlphabeticalPlayerRoster().filter(p=>p.active!==false).map(p=>p.name);
  const participants=bossParticipants(day);
  return `<div class="card boss-setup-card${_bossPanelOpen?' expanded':''}">
    <div class="crazy-day-top"><div class="crazy-day-title">
      <strong>Fight the Boss · ${enabled?'ON':'OFF'}</strong>
      <span>One challenge per competition. Beat the Boss: +2. Lose or tie: −5.</span>
    </div><button class="crazy-day-toggle" id="boss-expand" type="button" aria-expanded="${_bossPanelOpen}" aria-label="Configure Fight the Boss"></button></div>
    <div class="boss-setup-options" ${_bossPanelOpen?'':'hidden'}>
      <p class="mono dim">Optional for each player. Challenges stack with normal day points. The Boss wins ties.</p>
      <button type="button" class="btn ${enabled?'btn-s':'btn-p'}" id="boss-switch" ${!day||finished?'disabled':''}>${enabled?'Turn Off':'Activate Fight the Boss'}</button>
      ${enabled?`<div class="boss-admin-fields">
        <label for="boss-time-input">Secret Boss time</label>
        <input type="time" id="boss-time-input" value="${esc(cfg.time||'')}" ${finished?'disabled':''}>
        <p class="mono dim">The time appears in TODAY only after betting closes. Do not share the admin screen before then.</p>
        <div class="boss-player-list">${names.map(name=>{
          const checked=participants.some(n=>nameKey(n)===nameKey(name));
          const used=bossHasPlayed(name,day);
          return `<label class="boss-player-option"><span>${esc(name)} ${used?'<small>· Already challenged</small>':''}</span>
          <input type="checkbox" data-boss-player="${esc(name)}" ${checked?'checked':''} ${used||finished?'disabled':''}></label>`;
        }).join('')}</div>
        <button type="button" class="btn btn-p" id="boss-save" ${finished?'disabled':''}>Save Boss Challenge</button>
      </div>`:''}
    </div></div>`;
}
function bindBossSettings() {
  const root=document.getElementById('tab-settings');
  if (!root || root.dataset.bossBound) return;
  root.dataset.bossBound='1';
  root.addEventListener('click',async e=>{
    const btn=e.target.closest('button');
    if (!btn) return;
    if (btn.id==='boss-expand') {
      _bossPanelOpen=!_bossPanelOpen;
      const card=root.querySelector('.boss-setup-card');
      if(card)card.outerHTML=renderBossSetupCard(S.today);
      return;
    }
    if (btn.id!=='boss-switch' && btn.id!=='boss-save') return;
    const day=S.today;
    if (!day || day.wrapTime) return;
    const previous=cloneState();
    if(btn.id==='boss-switch') {
      day.fightTheBoss=bossConfig(day)?null:{enabled:true,time:'',players:[]};
    } else {
      const time=root.querySelector('#boss-time-input')?.value || '';
      const players=[...root.querySelectorAll('[data-boss-player]:checked')].map(el=>el.dataset.bossPlayer);
      if(!isValidHM(time)){toast('Enter a valid Boss time','err');return;}
      if(players.some(name=>bossHasPlayed(name,day))){toast('A player already used their Boss challenge','err');return;}
      day.fightTheBoss={enabled:true,time,players};
    }
    if(!await saveS()){restoreAfterFailedSave(previous);return;}
    toast('Fight the Boss settings saved','ok');
    render();
  });
}

let _stealDayPanelOpen = false;
function renderStealDaySetupCard(day=S.today) {
  const enabled = isStealTheDay(day);
  const editable = !!(day && (day.unit || 'main') === 'main' && !day.wrapTime && !(day.guesses||[]).some(g => g.time));
  return `<div class="card steal-day-card${_stealDayPanelOpen?' expanded':''}">
    <div class="crazy-day-top"><div class="crazy-day-title">
      <strong>Steal the Day · ${enabled?'ON':'OFF'}</strong>
      <span>Shared bets allowed. Each winner gets +2; N winners steal from N bets on each side (spillover at the edges).</span>
    </div><button class="crazy-day-toggle" id="steal-day-expand" type="button" aria-label="Configure Steal the Day" aria-expanded="${_stealDayPanelOpen}"></button></div>
    <div class="steal-day-options" ${_stealDayPanelOpen?'':'hidden'}>
      <p class="mono dim">One unique time per player. At least three valid bets. No shared times.</p>
      <p class="mono dim">Regular or exact winner: +2 points. Two nearest players: −1 each. Negative scores are allowed. No other points are awarded.</p>
      <p class="mono dim">If the winner is first or last, the next two bets on that side lose one point each.</p>
      ${!editable?'<p class="mono dim">Settings lock when bets are confirmed. Select an unplayed Main Unit.</p>':''}
      <div class="steal-day-actions"><button type="button" class="btn ${enabled?'btn-s':'btn-p'}" id="steal-day-switch" ${editable?'':'disabled'}>${enabled?'Turn Off':'Activate Steal the Day'}</button></div>
    </div>
  </div>`;
}
function bindStealDaySettings() {
  const root = document.getElementById('tab-settings');
  if (!root || root.dataset.stealBound) return;
  root.dataset.stealBound = '1';
  root.addEventListener('click', async event => {
    const button = event.target.closest('button');
    if (!button) return;
    if (button.id === 'steal-day-expand') {
      _stealDayPanelOpen = !_stealDayPanelOpen;
      const card = root.querySelector('.steal-day-card');
      if (card) card.outerHTML = renderStealDaySetupCard(S.today);
      return;
    }
    if (button.id !== 'steal-day-switch') return;
    const day = S.today;
    if (!day || day.wrapTime || (day.guesses||[]).some(g => g.time) || (day.unit||'main')!=='main') return;
    if (!isStealTheDay(day) && (day.crazyDay?.enabled || chainedPairs(day).length || isCrownDay(day))) {
      toast('Turn off Crazy Day and Chained Together before activating Steal the Day', 'err');return;
    }
    const previous=cloneState();
    day.stealTheDay = isStealTheDay(day) ? null : {enabled:true};
    if (!await saveS()) {restoreAfterFailedSave(previous);return;}
    toast(isStealTheDay(day)?'Steal the Day activated':'Steal the Day turned off','ok');
    render();
  });
}

let _crownDayPanelOpen = false;
function renderCrownDaySetupCard(day=S.today) {
  const enabled = isCrownDay(day);
  const editable = !!(day && (day.unit || 'main') === 'main' && !day.wrapTime && !(day.guesses||[]).some(g => g.time));
  const holder = enabled ? day.crownDay.holder : previousCrownWinner(day);
  return `<div class="card crown-day-card${_crownDayPanelOpen?' expanded':''}">
    <div class="crazy-day-top"><div class="crazy-day-title">
      <strong>Crown Day · ${enabled?'ON':'OFF'}</strong>
      <span>The previous Main Unit winner earns +1 if their own bet or a direct neighbor wins.</span>
    </div><button class="crazy-day-toggle" id="crown-day-expand" type="button" aria-label="Configure Crown Day" aria-expanded="${_crownDayPanelOpen}"></button></div>
    <div class="crown-day-options" ${_crownDayPanelOpen?'':'hidden'}>
      <p class="mono dim">Crown Holder: <strong>${holder ? esc(holder) : 'No eligible previous-day winner'}</strong></p>
      <p class="mono dim">If a neighboring bet wins, the actual winner receives normal points and the Crown Holder receives +1, even on an Exact Wrap.</p>
      <p class="mono dim">If the Crown Holder wins with their own bet, they receive only their normal win points. The first and last bets have just one neighbor.</p>
      ${!editable?'<p class="mono dim">Settings lock when bets are confirmed. Select an unplayed Main Unit.</p>':''}
      <div class="crown-day-actions"><button type="button" class="btn ${enabled?'btn-s':'btn-p'}" id="crown-day-switch" ${editable && (enabled || holder)?'':'disabled'}>${enabled?'Turn Off':'Activate Crown Day'}</button></div>
    </div>
  </div>`;
}
function bindCrownDaySettings() {
  const root = document.getElementById('tab-settings');
  if (!root || root.dataset.crownBound) return;
  root.dataset.crownBound = '1';
  root.addEventListener('click', async event => {
    const button = event.target.closest('button');
    if (!button) return;
    if (button.id === 'crown-day-expand') {
      _crownDayPanelOpen = !_crownDayPanelOpen;
      const card = root.querySelector('.crown-day-card');
      if (card) card.outerHTML = renderCrownDaySetupCard(S.today);
      return;
    }
    if (button.id !== 'crown-day-switch') return;
    const day = S.today;
    if (!day || day.wrapTime || (day.guesses||[]).some(g => g.time) || (day.unit||'main')!=='main') return;
    if (!isCrownDay(day) && (day.crazyDay?.enabled || chainedPairs(day).length || isStealTheDay(day))) {
      toast('Turn off other Extra Rules before activating Crown Day','err');return;
    }
    const holder = isCrownDay(day) ? null : previousCrownWinner(day);
    if (!isCrownDay(day) && !holder) {toast('No eligible previous Main Unit winner','err');return;}
    const previous = cloneState();
    day.crownDay = isCrownDay(day) ? null : {enabled:true,holder};
    if (!await saveS()) {restoreAfterFailedSave(previous);return;}
    toast(isCrownDay(day)?'Crown Day activated':'Crown Day turned off','ok');
    render();
  });
}

