async function cancelCrazyDayForSafety() {
  if (
    !IS_ADMIN ||
    !S.today?.crazyDay ||
    (S.today.unit || 'main') !== 'main' ||
    S.today.wrapTime ||
    S.today.guesses?.some(g => g.time)
  ) return true;
  const prevS =
    cloneState();

  const gameDate =
    displayToISO(S.today.date);

  setCrazyDayForLiveGameDate(
    gameDate,
    null
  );

  _crazyDayPanelOpen = false;
  const saved = await saveS();
  if (!saved) {
    restoreAfterFailedSave(prevS);
    return false;
  }
  toast('Crazy Day canceled', 'ok');
  return true;
}

